// Authored teaching notes. Each row is topic-specific; never substitute a generic lesson.
// id, explanation, worked fragment, exercise, question/correct/distractors, pitfall.
export const focusedLessons = [
[7, 'ژنریک جاوا در زمان کامپایل قرارداد نوع را بررسی می‌کند؛ List<Integer> زیرنوع List<Number> نیست. از ? extends برای خواندن و ? super برای افزودن استفاده کن. برخلاف تایپ TypeScript، پارامتر نوع جاوا نیز غالباً در runtime پاک می‌شود؛ new T() مجاز نیست.', 'static <T> void copy(List<? extends T> from, List<? super T> to) {\n    for (T value : from) to.add(value);\n}', 'متد copy را با List<Integer> و List<Number> آزمایش کن؛ تلاش برای افزودن Double به مبدا Integer باید کامپایل نشود.', ['برای مقصدی که Integer می‌پذیرد کدام مناسب است؟', 'List<? super Integer>', 'List<? extends Integer>', 'List<?> با افزودن مستقیم هر Object'], 'raw type و cast اجباری ایمنی قرارداد را دور می‌زنند؛ warning را پنهان نکن.'],
[8, 'Checked exception در امضای متد اعلام یا مدیریت می‌شود؛ RuntimeException چنین اجباری ندارد. خطای دامنه را از خطای زیرساخت جدا کن و هنگام ترجمه exception علت اصلی را حفظ کن. try-with-resources منابع AutoCloseable را حتی در شکست می‌بندد.', 'try (var input = Files.newInputStream(path)) {\n    return input.readAllBytes();\n} catch (IOException cause) {\n    throw new UncheckedIOException("Cannot read order", cause);\n}', 'یک فایل موقت بخوان و مسیر ناموجود را تست کن؛ cause و بسته‌شدن stream را بررسی کن.', ['هنگام ترجمه IOException چه چیزی حفظ شود؟', 'علت اصلی در cause', 'فقط متن getMessage بدون cause', 'نادیده‌گرفتن خطا و برگرداندن آرایه خالی'], 'Exception را با return null نپوشان؛ خطای قابل انتظار را با HTTP response یکی نکن.'],
[9, 'SOLID ابزار کنترل تغییر است، نه دستور ساخت interface برای هر کلاس. سرویس سفارش باید به قرارداد پرداخت وابسته باشد، نه SDK یک درگاه. جایگزینی پیاده‌سازی نباید شرط‌های قرارداد ورودی و خروجی را بشکند.', 'interface PaymentPort { Receipt charge(Money amount); }\nfinal class Checkout {\n    private final PaymentPort payments;\n    Checkout(PaymentPort payments) { this.payments = payments; }\n}', 'برای PaymentPort یک fake بساز و نشان بده تغییر درگاه، منطق سفارش را تغییر نمی‌دهد.', ['interface پرداخت کجا تعریف شود؟', 'نزدیک نیاز لایه مصرف‌کننده و مستقل از SDK', 'داخل کلاس SDK درگاه و وابسته به پاسخ اختصاصی آن', 'به ازای هر متد getter یک interface مستقل'], 'تعداد زیاد abstraction بدون یک نقطه تغییر واقعی، خواندن و تست را سخت می‌کند.'],
[10, 'اعتبارسنجی شکل درخواست با اعتبار دامنه فرق دارد: quantity مثبت است اما موجودی کافی نیازمند داده فعلی انبار است. invariant باید داخل دامنه نیز حفظ شود تا مسیرهای غیر HTTP نتوانند آن را دور بزنند.', 'record OrderLine(String sku, int quantity) {\n    OrderLine {\n        if (sku == null || sku.isBlank() || quantity < 1)\n            throw new IllegalArgumentException("Invalid line");\n    }\n}', 'برای quantity صفر، منفی و یک، تست مرزی بنویس؛ ساخت مستقیم OrderLine نامعتبر نیز باید شکست بخورد.', ['کنترل موجودی کافی در کدام دسته است؟', 'قاعده دامنه وابسته به داده و تراکنش', 'فقط اعتبارسنجی JSON', 'فقط محدودیت اندازه متن sku'], 'validate سپس update بدون تراکنش در حضور درخواست همزمان کافی نیست.'],
[11, 'Stream یک pipeline تنبل است؛ terminal operation اجرای آن را آغاز می‌کند. map تبدیل، filter انتخاب و reduce تجمیع است. side effect در map، مخصوصاً با parallel، ترتیب و ایمنی را مبهم می‌کند.', 'var total = lines.stream()\n    .filter(line -> line.quantity() > 0)\n    .map(line -> line.unitPrice().multiply(BigDecimal.valueOf(line.quantity())))\n    .reduce(BigDecimal.ZERO, BigDecimal::add);', 'مجموع سفارش خالی و چند قلم را تست کن؛ از تغییر متغیر بیرون stream پرهیز کن.', ['بدون terminal operation چه اتفاقی می‌افتد؟', 'پردازش pipeline معمولاً آغاز نمی‌شود', 'تمام mapها هنگام تعریف اجرا می‌شوند', 'به طور خودکار یک thread جدید ساخته می‌شود'], 'parallelStream برای کار I/O یا تراکنش دیتابیس انتخاب پیش‌فرض مناسبی نیست.'],
[12, 'SLF4J قرارداد logging است؛ backend تعیین می‌کند رخداد کجا و چگونه ذخیره شود. لاگ پارامتری ساخت رشته بیهوده را کم می‌کند. رخداد عملیاتی را با شناسه سفارش ثبت کن، نه داده حساس کاربر.', 'private static final Logger log = LoggerFactory.getLogger(OrderService.class);\n// In a service method:\nlog.info("order_created orderId={} itemCount={}", orderId, count);', 'یک مسیر موفق و یک شکست را log کن؛ ثابت کن token و payload شخصی در خروجی نیست.', ['برای رخداد ثبت سفارش چه داده‌ای مناسب‌تر است؟', 'شناسه سفارش و نتیجه عملیات', 'Authorization header کامل', 'رمز عبور برای دیباگ'], 'logging جای error handling نیست؛ یک exception را در تمام لایه‌ها دوباره log نکن.'],
[13, 'Record برای حامل داده با equality بر اساس componentها مناسب است؛ immutability آن سطحی است. اگر component یک List قابل تغییر باشد، final بودن reference محتوا را ثابت نمی‌کند. برای ورودی mutable نسخه دفاعی بساز.', 'record Basket(List<String> skus) {\n    Basket { skus = List.copyOf(skus); }\n}', 'لیست مبدا را پس از ساخت Basket تغییر بده؛ مقدار record نباید تغییر کند. null element را نیز بررسی کن.', ['آیا record دارای List خودبه‌خود عمیقاً immutable است؟', 'خیر؛ باید کپی دفاعی یا ساختار immutable انتخاب شود', 'بله؛ JVM تمام اشیای داخل آن را freeze می‌کند', 'فقط با اضافه‌کردن synchronized به accessor'], 'Entity JPA را صرفاً برای کوتاه‌شدن کد record نکن؛ lifecycle و هویت آن متفاوت است.'],
[14, 'Optional برای بیان نبود نتیجه، مخصوصاً در خروجی query، مفید است. orElse آرگومان خود را پیش از فراخوانی ارزیابی می‌کند؛ orElseGet ساخت مقدار جایگزین را به زمان نیاز عقب می‌اندازد. get بدون بررسی همان خطای کنترل‌نشده را بازمی‌گرداند.', 'Order order = repository.findById(id)\n    .orElseThrow(() -> new OrderNotFoundException(id));', 'ساخت جایگزین پرهزینه را با orElse و orElseGet مقایسه کن؛ تعداد فراخوانی supplier را تست کن.', ['برای ساخت تنبل مقدار جایگزین چه انتخابی درست است؟', 'orElseGet(() -> expensive())', 'orElse(expensive())', 'get() سپس catch کردن همه exceptionها'], 'Optional را برای هر فیلد DTO یا پارامتر اجباری به‌کار نبر؛ قرارداد مشخص مهم‌تر است.'],
[15, 'نام خوب هدف و واحد اندازه را آشکار می‌کند. به جای متد عمومی process، مرز کسب‌وکار مانند reserveStock را نام ببر. متد کوچک باید یک سطح abstraction داشته باشد؛ کوتاهی به تنهایی معیار کیفیت نیست.', 'Duration reservationTimeout = Duration.ofSeconds(30);\nboolean canReserve(int requested, int available) {\n    return requested > 0 && available >= requested;\n}', 'کد دارای timeout عددی بدون واحد و نام‌های data/process را بازنام‌گذاری کن؛ رفتار تست‌ها ثابت بماند.', ['کدام نام ابهام واحد را کمتر می‌کند؟', 'Duration reservationTimeout', 'int timeout', 'long value'], 'کامنت توضیح نام بد نیست؛ دلیل تصمیم یا محدودیت را توضیح بده.'],
[16, 'Refactor یعنی تغییر ساختار با حفظ رفتار مشاهده‌شدنی. مبلغ را با BigDecimal و currency مدل کن؛ double برای جمع پول مناسب نیست. scale و rounding تصمیم دامنه‌اند و باید صریح باشند.', 'record Money(BigDecimal amount, Currency currency) {\n    Money {\n        Objects.requireNonNull(currency);\n        amount = amount.setScale(currency.getDefaultFractionDigits(), RoundingMode.HALF_UP);\n    }\n}', 'جمع دو Money هم‌ارز را بساز و جمع ارزهای متفاوت را رد کن؛ قبل از refactor تست رفتار بنویس.', ['برای مقدار ده‌دهی دقیق پول چه ورودی مناسب است؟', 'new BigDecimal("0.10")', 'new BigDecimal(0.1)', 'float و گردکردن پس از هر جمع بدون سیاست'], 'مقایسه BigDecimal با equals به scale حساس است؛ برای برابری عددی compareTo را آگاهانه انتخاب کن.'],
[17, 'Instant یک نقطه روی خط زمان است؛ LocalDate تاریخ بدون timezone و ZonedDateTime زمان همراه منطقه است. برای آزمون از Clock تزریق‌شده استفاده کن. مهلت سفارش را با Instant بسنج، نه رشته تاریخ محلی.', 'Clock clock = Clock.fixed(Instant.parse("2026-01-01T00:00:00Z"), ZoneOffset.UTC);\nInstant expiresAt = clock.instant().plus(Duration.ofMinutes(15));', 'انقضای سفارش را درست قبل، دقیقاً روی مرز و بعد از مهلت تست کن؛ timezone نمایش را جدا نگه دار.', ['برای ثبت لحظه ایجاد سفارش چه نوعی مناسب‌تر است؟', 'Instant', 'LocalTime بدون تاریخ', 'String با فرمت نمایش کاربر'], 'یک روز تقویمی همیشه معادل ۲۴ ساعت نیست؛ تغییر ساعت و timezone را در برنامه‌ریزی لحاظ کن.'],
[18, 'Commit کوچک باید یک تغییر قابل توضیح و قابل برگشت باشد. در review ابتدا صحت، تست و قرارداد عمومی را ببین؛ اختلاف سبک را formatter حل کند. تغییر schema را همراه سازگاری نسخه قبلی سرویس بررسی کن.', 'bash:git switch -c feature/order-validation\ngit diff --check\ngit diff --stat\ngit status --short', 'یک تغییر validation با تست و توضیح قبل/بعد در commit مستقل آماده کن؛ secrets و خروجی build وارد diff نشوند.', ['برای review مؤثر کدام تغییر مناسب‌تر است؟', 'یک رفتار مشخص با تست مرتبط و diff محدود', 'ترکیب ارتقای framework و تغییر دامنه و فرمت کل repo', 'فقط توضیح شفاهی بدون تست یا diff'], 'force push روی شاخه مشترک بدون هماهنگی تاریخچه همکار را به خطر می‌اندازد.'],
[19, 'هر thread stack اجرای خود را دارد و اشیای معمول در heap مشترک قرار می‌گیرند. GC اشیای غیرقابل‌دسترسی را جمع می‌کند، نه اشیایی که صرفاً دیگر لازمشان نداری. cache یا listener دارای reference می‌تواند نشت منطقی بسازد.', 'bash:java -Xms128m -Xmx512m -Xlog:gc* -jar app.jar\njcmd <PID> GC.heap_info', 'با یک cache بدون سقف مصرف heap را مشاهده کن؛ سپس eviction اضافه کن و روند مصرف را مقایسه کن.', ['آیا GC شیء قابل دسترس ولی بی‌مصرف را الزاماً حذف می‌کند؟', 'خیر؛ reachable بودن مانع جمع‌آوری است', 'بله؛ JVM نیاز تجاری را تشخیص می‌دهد', 'بله؛ به محض پایان هر HTTP request'], 'افزایش Xmx علت نگه‌داشتن referenceها را درمان نمی‌کند.'],
[20, 'ExecutorService اجرای task را از ساخت thread جدا می‌کند. Future.get نتیجه یا خطا را آشکار می‌کند؛ اگر نتیجه را رها کنی ممکن است شکست task را نبینی. در Java 25 executor را با try-with-resources ببند.', 'try (var pool = Executors.newFixedThreadPool(2)) {\n    Future<Integer> result = pool.submit(() -> 21 * 2);\n    System.out.println(result.get());\n}', 'سه task با یک شکست اجرا کن؛ خطای ExecutionException را با حفظ cause بررسی کن و executor را ببند.', ['submit شکست task را کجا در اختیار مصرف‌کننده می‌گذارد؟', 'در Future و فراخوانی get', 'همیشه مستقیماً در thread فراخواننده submit', 'آن را خودکار retry می‌کند'], 'صف newFixedThreadPool بدون سقف است؛ برای بار کنترل‌نشده executor با صف محدود لازم است.'],
[21, 'count++ یک عملیات اتمیک نیست. volatile visibility می‌دهد اما read-modify-write را اتمیک نمی‌کند. synchronized علاوه بر mutual exclusion رابطه happens-before می‌سازد؛ برای invariant چندفیلدی قفل مشترک یا طراحی immutable لازم است.', 'final class Counter {\n    private int value;\n    synchronized void increment() { value++; }\n    synchronized int value() { return value; }\n}', 'با چند thread شمارنده را افزایش بده؛ سپس volatile تنها را جایگزین کن و تفاوت تضمین را توضیح بده.', ['آیا volatile int برای count++ کافی است؟', 'خیر؛ افزایش چندمرحله‌ای است', 'بله؛ تمام عملیات روی آن قفل می‌شوند', 'فقط وقتی CPU بیشتر از یک هسته دارد'], 'عبور تصادفی یک تست همزمانی اثبات thread safety نیست.'],
[22, 'در یک process می‌توان check و decrement را زیر یک قفل واحد انجام داد؛ این قفل میان چند instance مشترک نیست. برای سفارش واقعی، invariant موجودی باید در دیتابیس و تراکنش محافظت شود.', 'synchronized boolean reserve(int quantity) {\n    if (quantity < 1 || stock < quantity) return false;\n    stock -= quantity;\n    return true;\n}', 'موجودی یک را با دو درخواست همزمان امتحان کن؛ دقیقاً یک رزرو موفق باشد. محدودیت چند instance را بنویس.', ['قفل synchronized از موجودی در دو JVM محافظت می‌کند؟', 'خیر؛ قفل حافظه محلی process است', 'بله؛ اگر کلاس‌ها نام یکسان داشته باشند', 'بله؛ با static شدن هر فیلد'], 'check خارج از قفل و decrement داخل قفل هنوز race condition دارد.'],
[23, 'پیش از تغییر GC یا thread pool، داده جمع کن. JFR نمونه‌های CPU، allocation، قفل و I/O را کنار هم نشان می‌دهد. thread dump برای دیدن محل انتظار است؛ تعداد زیاد WAITING الزاماً مشکل نیست.', 'bash:jcmd <PID> JFR.start name=orders settings=profile duration=60s filename=/tmp/orders.jfr\njcmd <PID> Thread.print', 'یک endpoint کند را زیر بار محدود اجرا کن؛ با JFR مشخص کن وقت روی CPU صرف می‌شود یا انتظار اتصال DB.', ['برای تصمیم تیونینگ اولین گام چیست؟', 'اندازه‌گیری زیر بار نماینده', 'افزایش همه poolها به ۱۰۰۰', 'خاموش‌کردن log و فرض حل مشکل'], 'یک snapshot بدون workload و baseline قابل تفسیر مطمئن نیست.'],
[24, 'حد حافظه کانتینر فقط heap نیست؛ metaspace، stack، direct buffer و native memory هم مصرف دارند. MaxRAMPercentage سهم heap را تعیین می‌کند، نه سقف کل process. فاصله امن تا حد container را با اندازه‌گیری انتخاب کن.', 'bash:java -XX:MaxRAMPercentage=60 -XX:+ExitOnOutOfMemoryError -jar app.jar\ndocker stats', 'با limit مشخص Docker، heap و RSS را مقایسه کن؛ توضیح بده چرا Xmx برابر کل limit خطرناک است.', ['حد ۵۱۲MB کانتینر یعنی می‌توان Xmx=512m گذاشت؟', 'معمولاً خیر؛ حافظه غیر heap هم نیاز است', 'بله؛ stack داخل همان heap است', 'بله؛ Docker متاسپیس را حساب نمی‌کند'], 'OOMKilled ممکن است بدون Java OutOfMemoryError رخ دهد؛ exit code و رخداد container را نیز ببین.'],
[25, 'در DI، ساخت و اتصال وابستگی‌ها از منطق سرویس جدا می‌شود. Constructor injection وابستگی اجباری را آشکار می‌کند و تست بدون container را ساده می‌سازد. Spring singleton در هر ApplicationContext است، نه singleton سراسری شبکه.', '@Service\nclass CheckoutService {\n    private final PaymentPort payments;\n    CheckoutService(PaymentPort payments) { this.payments = payments; }\n}', 'CheckoutService را با یک fake از PaymentPort بدون Spring بساز؛ سپس همان قرارداد را به bean متصل کن.', ['مزیت constructor injection چیست؟', 'وابستگی اجباری آشکار و تست ساده‌تر', 'تضمین thread safety تمام فیلدها', 'ساخت یک instance در کل cluster'], 'field injection وابستگی پنهان و ساخت مستقل برای تست را دشوار می‌کند.'],
[26, 'Spring پس از ساخت bean، وابستگی‌ها را متصل و callbackهای lifecycle را اجرا می‌کند. @Bean برای اشیای کتابخانه بیرونی مناسب است. کاری مثل migration یا تماس شبکه نامحدود در constructor شروع سرویس را شکننده می‌کند.', '@Configuration\nclass TimeConfig {\n    @Bean Clock clock() { return Clock.systemUTC(); }\n}', 'Clock را bean کن و در تست Clock.fixed جایگزین کن؛ constructor نباید شبکه را صدا بزند.', ['کدام مورد گزینه مناسب @Bean است؟', 'ساخت وابستگی third-party با تنظیمات مشخص', 'اجرای تمام queryها در constructor هر request', 'ذخیره state مشترک کاربر در singleton'], 'prototype داخل singleton با تزریق معمول، در هر فراخوانی خودکار دوباره ساخته نمی‌شود.'],
[27, 'Dependency inversion می‌گوید سیاست دامنه نباید به جزئیات persistence وابسته باشد. port را با زبان نیاز دامنه تعریف کن؛ adapter آن را با JPA پیاده کند. لازم نیست تمام CRUD یک ORM به هسته نشت کند.', 'interface StockPort { boolean reserve(String sku, int quantity); }\nfinal class PlaceOrder {\n    private final StockPort stock;\n    PlaceOrder(StockPort stock) { this.stock = stock; }\n}', 'یک adapter حافظه‌ای برای StockPort و تست use case بدون Spring بنویس.', ['آیا port دامنه باید JpaRepository را extend کند؟', 'نه؛ قرارداد دامنه از ORM مستقل بماند', 'بله؛ وگرنه Spring هیچ bean نمی‌سازد', 'فقط اگر controller مستقیماً DB را صدا بزند'], 'مرز معماری را با تعداد packageها نسنج؛ جهت dependency مهم است.'],
[28, 'Boot تنظیمات متداول را براساس classpath و شرایط فعال می‌کند؛ magic بدون قاعده نیست. کلاس اصلی در package ریشه component scan باشد. وقتی auto-configuration چیزی را نساخت، گزارش conditions را بررسی کن.', '@SpringBootApplication\npublic class OrderApplication {\n    public static void main(String[] args) {\n        SpringApplication.run(OrderApplication.class, args);\n    }\n}', 'یک endpoint سلامت ساده بساز؛ با --debug دلیل فعال‌شدن auto-configuration وب را پیدا کن.', ['محل مناسب کلاس اصلی کجاست؟', 'package ریشه مشترک componentها', 'داخل package تصادفی خارج از سرویس‌ها', 'فقط کنار pom.xml بدون package'], 'ساخت پروژه از initializer به معنی درست‌بودن نسخه‌های دستی و dependencyهای ناسازگار نیست.'],
[29, 'ConfigurationProperties تنظیمات مرتبط را به یک مدل تایپ‌دار متصل می‌کند؛ validation خطای پیکربندی را هنگام شروع آشکار می‌سازد. Duration از عدد timeout بدون واحد روشن‌تر است.', '@Validated\n@ConfigurationProperties("orders")\npublic record OrderProperties(@NotNull Duration timeout) {}\n// Register via @ConfigurationPropertiesScan on the application.', 'orders.timeout را با 5s تنظیم کن؛ نبود مقدار و یک مقدار نامعتبر باید خطای شروع قابل فهم ایجاد کند.', ['برای گروه تنظیمات مرتبط چه انتخابی مناسب‌تر است؟', 'ConfigurationProperties با validation', 'خواندن پراکنده getenv داخل متدهای دامنه', 'hardcode کردن URL محیط production'], 'صرف تعریف record آن را bean نمی‌کند؛ scan یا EnableConfigurationProperties لازم است.'],
[30, 'Profile برای تفاوت‌های رفتاری محیط است؛ secret نباید در application-prod.yml commit شود. ترتیب منابع configuration تعیین می‌کند کدام مقدار برنده است. تنظیمات عملیاتی باید از خارج artifact قابل تزریق باشند.', 'yaml:spring:\n  config:\n    activate:\n      on-profile: prod\norders:\n  timeout: ${ORDER_TIMEOUT:5s}', 'یک مقدار را در فایل و environment متفاوت بده؛ مقدار موثر را بدون log کردن secrets بررسی کن.', ['رمز production کجا نگه‌داری شود؟', 'secret store یا ورودی محیط با دسترسی کنترل‌شده', 'در git با نام application-prod.yml', 'در پاسخ عمومی actuator/env'], 'Profile مرز امنیت نیست؛ endpointهای مدیریتی و config exposure جدا کنترل شوند.'],
[31, 'Controller قرارداد HTTP را به use case تبدیل می‌کند؛ نباید تراکنش، SQL و قواعد تجاری در آن انباشته شود. binding مسیر، query و body را صریح انتخاب کن و DTO خروجی را از Entity جدا نگه دار.', '@RestController\n@RequestMapping("/api/orders")\nclass OrderController {\n    @GetMapping("/{id}")\n    OrderResponse get(@PathVariable UUID id) { return orders.get(id); }\n}', 'GET با UUID معتبر و نامعتبر را تست کن؛ ورودی نامعتبر 400 و سفارش غایب 404 باشد.', ['Controller بهتر است چه چیزی برگرداند؟', 'DTO قرارداد API', 'Entity با روابط lazy و فیلدهای داخلی', 'همیشه String شامل JSON دست‌ساز'], 'annotationها جای طراحی قرارداد و تست HTTP را نمی‌گیرند.'],
[32, 'Bean Validation شکل ورودی را بررسی می‌کند؛ روی body از @Valid استفاده کن و برای collection، validation تو‌در‌تو لازم است. DTO ورودی با entity یکسان نیست؛ جلوگیری از mass assignment مهم است.', 'record CreateOrder(@NotBlank String customerId,\n    @NotEmpty List<@Valid Line> items) {}\nrecord Line(@NotNull UUID productId, @Positive int quantity) {}', 'body خالی، items خالی و quantity صفر را تست کن؛ خطا باید مسیر فیلد نامعتبر را نشان دهد.', ['برای validation آیتم‌های داخل لیست چه چیزی لازم است؟', 'فعال‌سازی validation تو‌در‌تو با @Valid', 'فقط @NotEmpty روی لیست', 'نام‌گذاری فیلد به validatedItems'], 'فعال‌بودن dependency validation و فراخوانی @Valid را جدا بررسی کن.'],
[33, 'Status code بخشی از قرارداد است: 201 برای ایجاد، 404 برای نبود منبع، 409 برای تعارض با وضعیت فعلی. 204 بدنه ندارد. idempotent بودن به معنای یکسان‌بودن تمام responseها نیست؛ اثر تکرار درخواست مهم است.', 'return ResponseEntity.created(URI.create("/api/orders/" + order.id()))\n    .body(order);', 'برای ایجاد سفارش status، Location و body را تست کن؛ 204 را بدون body تولید کن.', ['در ایجاد موفق یک منبع جدید کدام مناسب است؟', '201 همراه Location منبع', '200 برای تمام نتیجه‌ها شامل خطا', '204 همراه JSON کامل سفارش'], 'خطای تجاری را در HTTP 200 با success=false پنهان نکن.'],
[34, 'مسیر ایجاد سفارش باید request validation، use case تراکنشی و DTO پاسخ را به هم وصل کند. شناسه و قیمت نهایی باید تحت اختیار سرور باشند؛ قیمت ارسالی کلاینت منبع حقیقت نیست.', '@PostMapping\nResponseEntity<OrderResponse> create(@Valid @RequestBody CreateOrder request) {\n    var result = orders.create(request);\n    return ResponseEntity.created(URI.create("/api/orders/" + result.id())).body(result);\n}', 'POST و سپس GET همان سفارش را با MockMvc یا curl آزمایش کن؛ client نتواند total را تعیین کند.', ['قیمت نهایی سفارش از کجا تعیین شود؟', 'داده معتبر سمت سرور و قواعد قیمت‌گذاری', 'فیلد total در body کلاینت بدون بررسی', 'جمع رشته‌های ارسالی در controller'], 'افزودن endpoint بدون مسیر خطا و contract test، API کامل نمی‌سازد.'],
[35, 'Exception handler خطاهای دامنه را به قرارداد HTTP تبدیل می‌کند. ProblemDetail مدل استاندارد خطاست؛ stack trace و SQL نباید به client نشت کنند. کد پایدار خطا و traceId برای پشتیبانی مفیدند.', '@ExceptionHandler(OrderNotFoundException.class)\nProblemDetail notFound(OrderNotFoundException error) {\n    return ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, "Order not found");\n}', 'برای not-found و خطای نامنتظره تست بنویس؛ پاسخ 500 نباید stack trace داشته باشد.', ['در پاسخ عمومی خطای داخلی چه چیزی مناسب است؟', 'پیام امن و شناسه رهگیری', 'SQL کامل و password اتصال', 'نام تمام کلاس‌ها و stack trace'], 'برای هر Exception نامشخص 400 برنگردان؛ خطای client و server را تفکیک کن.'],
[36, 'OpenAPI قرارداد قابل مصرف API است، نه فقط صفحه Swagger. schema، error response، pagination و security scheme باید رفتار واقعی را منعکس کنند. تولید مستندات به تنهایی تغییر ناسازگار را پیدا نمی‌کند.', 'yaml:paths:\n  /api/orders/{id}:\n    get:\n      responses:\n        "200":\n          description: Order found\n        "404":\n          description: Order not found', 'برای GET سفارش schema و دو response را مستند کن؛ یک contract test مغایرت body را آشکار کند.', ['OpenAPI بدون تست چه چیزی را تضمین نمی‌کند؟', 'تطابق رفتار واقعی پیاده‌سازی با قرارداد', 'امکان توصیف endpoint و schema', 'امکان تولید client از یک specification معتبر'], 'نسخه springdoc یا ابزار مستندات باید با نسخه Boot سازگار باشد.'],
[37, 'Service مرز اجرای use case و تراکنش است. اعتبار دامنه را در مدل و هماهنگی repositoryها را در service نگه دار. تماس شبکه کند را داخل تراکنش DB بی‌دلیل طولانی نکن.', '@Transactional\npublic OrderResponse place(CreateOrder request) {\n    var order = Order.create(request.customerId());\n    reserveInventory(request.items());\n    return OrderResponse.fromEntity(repository.save(order));\n}', 'اگر رزرو دوم شکست خورد، ثابت کن ذخیره سفارش و رزرو اول rollback می‌شوند.', ['مرز مناسب تراکنش ثبت سفارش معمولاً چیست؟', 'کل use case شامل تغییرات مرتبط دیتابیس', 'هر setter در entity به صورت مستقل', 'کل عمر HTTP connection و همه تماس‌های بیرونی'], 'private یا self-invoked بودن متد می‌تواند اعمال proxy تراکنشی را تغییر دهد.'],
[38, 'Repository دسترسی داده را پشت قرارداد مشخص پنهان می‌کند. query باید نیاز use case را بیان کند؛ برگرداندن همه جدول برای filter در حافظه مقیاس نمی‌گیرد. قرارداد empty، not-found و خطای DB را واضح نگه دار.', 'interface OrderRepository extends JpaRepository<Order, UUID> {\n    List<Order> findByCustomerIdOrderByCreatedAtDesc(String customerId);\n}', 'برای customer بدون سفارش و چند سفارش query بنویس؛ ترتیب نتیجه در تست مشخص باشد.', ['برای سفارش‌های یک مشتری چه رویکردی مناسب‌تر است؟', 'filter و sort در query دیتابیس', 'findAll و فیلتر تمام جدول در JVM', 'نگه‌داشتن EntityManager مشترک static میان threadها'], 'JpaRepository یک abstraction زیرساختی است؛ در معماری hexagonal آن را به همه لایه‌ها نشت نده.'],
[39, 'Layered ساده و برای بسیاری سرویس‌ها کافی است؛ hexagonal مرز وابستگی دامنه به بیرون را پررنگ می‌کند. هزینه port و adapter وقتی توجیه دارد که تغییرپذیری یا تست مستقل ارزش واقعی بسازد.', 'text:web adapter -> application use case -> domain\npersistence adapter -> domain port\ndomain -X-> Spring MVC / JPA', 'وابستگی‌های سه package پروژه را رسم کن؛ یک import زیرساخت از domain را حذف کن.', ['معیار اصلی hexagonal چیست؟', 'جهت dependency و مرزهای قابل آزمون', 'داشتن دقیقاً شش package', 'ایجاد interface برای تمام کلاس‌ها'], 'جابه‌جایی فایل‌ها بدون تغییر coupling، اصلاح معماری محسوب نمی‌شود.'],
[40, 'Refactor معماری را با یک مسیر عمودی کوچک شروع کن. قرارداد use case را استخراج و adapter فعلی را نگه دار تا API نشکند. تست characterization رفتار قبلی را ثبت می‌کند.', 'record PlaceOrderCommand(String customerId, List<Line> lines) {}\ninterface PlaceOrderUseCase { UUID place(PlaceOrderCommand command); }', 'یک endpoint را به use case متصل کن؛ integration test قبل و بعد باید قرارداد یکسانی ببیند.', ['اولین گام کم‌ریسک refactor چیست؟', 'ثبت رفتار و تغییر یک مسیر کوچک', 'بازنویسی کل repo بدون تست', 'تغییر همزمان همه endpointها و schema'], 'تغییر interface عمومی را با refactor داخلی اشتباه نگیر؛ compatibility را ارزیابی کن.'],
[41, 'Pagination به ترتیب پایدار نیاز دارد؛ sort روی createdAt تنها در زمان‌های برابر مبهم است، id را tie-breaker کن. offset برای صفحه‌های عمیق هزینه دارد؛ keyset pagination برای پیمایش ترتیبی گزینه دیگر است.', 'sql:SELECT id, created_at FROM orders\nWHERE (created_at, id) < (:last_time, :last_id)\nORDER BY created_at DESC, id DESC\nLIMIT 20;', 'دو سفارش با زمان یکسان بساز؛ پیمایش صفحه‌ها نباید مورد تکراری یا جاافتاده تولید کند.', ['چرا id در sort اضافه می‌شود؟', 'برای شکستن تساوی و ترتیب پایدار', 'برای رمزگذاری cursor به صورت خودکار', 'برای حذف نیاز به index'], 'page size و فیلدهای sort قابل قبول را محدود کن؛ ورودی کاربر را SQL خام نکن.'],
[42, 'Liveness می‌پرسد process قابل ادامه است؛ readiness می‌پرسد ترافیک بگیرد یا نه. قطع DB مشترک نباید بی‌دلیل همه instanceها را restart کند. Actuator مدیریتی را کم‌دسترسی و کم‌افشا نگه دار.', 'yaml:management:\n  endpoints:\n    web:\n      exposure:\n        include: health,prometheus\n  endpoint:\n    health:\n      probes:\n        enabled: true', 'با قطع DB، liveness و readiness را جدا مشاهده کن و سیاست routing را توضیح بده.', ['قطع دیتابیس مشترک باید لزوماً liveness را fail کند؟', 'خیر؛ می‌تواند موج restart بی‌فایده بسازد', 'بله؛ restart همیشه DB را تعمیر می‌کند', 'بله؛ readiness و liveness یک مفهوم‌اند'], 'افشای env، heapdump یا تمام actuatorها روی پورت عمومی خطرناک است.'],
[43, 'Servlet Filter در زنجیره HTTP و بیرون MVC کار می‌کند؛ HandlerInterceptor به handlerهای MVC نزدیک‌تر است. برای correlation id یک Filter مناسب است؛ context را در finally پاک کن تا thread reuse داده درخواست قبلی را نشت ندهد.', 'MDC.put("requestId", UUID.randomUUID().toString());\ntry { chain.doFilter(request, response); }\nfinally { MDC.remove("requestId"); }', 'دو درخواست پشت سر هم و یک مسیر exception را تست کن؛ requestId نباید میان آن‌ها مشترک بماند.', ['چرا MDC در finally پاک می‌شود؟', 'جلوگیری از نشت context در threadهای بازاستفاده‌شده', 'جلوگیری از اجرای controller', 'تبدیل خودکار response به JSON'], 'برای authorization از interceptor سفارشی به جای زنجیره استاندارد Security استفاده نکن.'],
[44, 'Spring AOP معمولاً با proxy کار می‌کند. فراخوانی از بیرون proxy advice را اجرا می‌کند؛ this.method آن را دور می‌زند. Transaction، Async و Cache هم از همین محدودیت اثر می‌گیرند.', '@Service\nclass Checkout {\n    private final Billing billing;\n    Checkout(Billing billing) { this.billing = billing; }\n    void place() { billing.charge(); }\n}\n// Billing.charge is invoked through its Spring bean proxy.', 'یک self-invocation تراکنشی بساز؛ سپس متد را به bean جدا منتقل کن و فعال‌بودن تراکنش را مقایسه کن.', ['آیا this.transactionalMethod() الزاماً proxy را عبور می‌کند؟', 'خیر؛ فراخوانی داخلی معمولاً advice را دور می‌زند', 'بله؛ annotation تمام bytecodeها را تغییر می‌دهد', 'فقط اگر متد نام place داشته باشد'], 'annotation بدون درک مرز proxy می‌تواند حس کاذب امنیت یا تراکنش بسازد.'],
[45, 'Idempotency اثر درخواست تکراری را کنترل می‌کند. برای POST کلید، محدوده مالک، fingerprint درخواست و پاسخ ذخیره شود. همان کلید با payload متفاوت باید تعارض بدهد؛ cache حافظه‌ای در چند instance کافی نیست.', 'sql:CREATE TABLE idempotency_keys (\n  owner_id text NOT NULL, key text NOT NULL,\n  request_hash text NOT NULL, response jsonb,\n  PRIMARY KEY (owner_id, key)\n);', 'دو POST همزمان با کلید یکسان را تست کن؛ یک سفارش ایجاد شود و payload متفاوت با همان کلید رد شود.', ['همان کلید با payload متفاوت چه رفتاری می‌خواهد؟', 'تشخیص تعارض و عدم اجرای درخواست جدید', 'بازگرداندن سفارش هر مشتری با همان کلید', 'ساخت سفارش دوم و حذف اولی'], 'SELECT سپس INSERT بدون unique constraint در برابر race امن نیست.'],
[46, 'برای claim کلید تکرار از uniqueness دیتابیس استفاده کن و تغییر سفارش را در تراکنش هماهنگ بساز. خطای unique می‌تواند تراکنش JPA را rollback-only کند؛ ادامه query در همان تراکنش راه replay مطمئنی نیست.', 'sql:INSERT INTO idempotency_keys(owner_id,key,request_hash)\nVALUES (:owner,:key,:hash)\nON CONFLICT DO NOTHING\nRETURNING key;', 'رقابت دو درخواست، rollback عملیات و retry پس از قطع پاسخ را تست کن؛ هیچ رزرو دوباره‌ای ایجاد نشود.', ['پس از unique violation در تراکنش JPA چه چیزی خطرناک است؟', 'ادامه کار و فرض سالم‌بودن همان تراکنش', 'rollback و تصمیم retry در مرز بیرونی', 'اتکا به unique constraint برای تشخیص race'], 'Idempotency بدون scope کاربر می‌تواند پاسخ مشتری دیگری را افشا کند.'],
[47, 'نسخه API برای تغییر قرارداد ناسازگار است، نه هر deploy. افزودن فیلد اختیاری معمولاً آسان‌تر از حذف یا تغییر معنای فیلد موجود است. سیاست deprecation و پنجره سازگاری را مستند کن.', 'text:GET /api/v1/orders/{id}\nGET /api/v2/orders/{id}\n// Keep v1 contract tests while v1 clients are supported.', 'یک فیلد را با روش expand اضافه کن؛ تست client قدیمی باید همچنان موفق باشد.', ['تغییر کدام مورد معمولاً breaking است؟', 'تغییر نوع total از عدد به object بدون نسخه یا سازگاری', 'اضافه‌شدن endpoint مستقل', 'بهبود index داخلی دیتابیس'], 'کپی کل منطق دامنه برای هر نسخه نگه‌داری را دشوار می‌کند؛ adapter قرارداد را جدا کن.'],
[48, 'ایمیج runtime نباید Maven و سورس لازم‌نبودنی را حمل کند. JAR ساخته‌شده را با کاربر غیر root اجرا کن و signal را به JVM برسان. در Apple Silicon، build بومی از emulation غیرضروری جلوگیری می‌کند.', 'dockerfile:FROM eclipse-temurin:25-jre\nWORKDIR /app\nCOPY target/app.jar app.jar\nUSER 10001\nENTRYPOINT ["java", "-jar", "app.jar"]', 'JAR را بساز و container را با memory limit اجرا کن؛ SIGTERM باید به JVM برسد.', ['فرم مناسب ENTRYPOINT برای دریافت signal چیست؟', 'فرم exec آرایه‌ای', 'shell که JVM را در background می‌گذارد', 'اجرای Maven download در هر شروع container'], 'وجود java.version در pom به تنهایی JDK داخل Docker را تغییر نمی‌دهد.'],
[49, 'Entity با هویت پایدار و lifecycle در persistence context مدیریت می‌شود. persist شیء جدید را managed می‌کند؛ تغییر شیء managed با dirty checking ذخیره می‌شود. EntityManager برای اشتراک همزمان مستقیم میان threadها نیست.', 'Order order = new Order(customerId, key);\nentityManager.persist(order);\nentityManager.flush();\n// flush sends SQL; commit still determines transaction success.', 'تفاوت persist، flush و commit را با rollback پس از flush مشاهده کن.', ['آیا flush یعنی تراکنش commit شده است؟', 'خیر؛ SQL ارسال شده ولی rollback ممکن است', 'بله؛ تمام lockها آزاد شده‌اند', 'بله؛ flush همان commit با نام دیگر است'], 'شناسه تولیدشده در حافظه اثبات ذخیره پایدار پس از commit نیست.'],
[50, 'Spring Data پیاده‌سازی repository را تولید می‌کند؛ query derivation از نام متد قرارداد مشخص می‌سازد. save بسته به وضعیت entity ممکن است persist یا merge کند؛ merge نمونه managed برمی‌گرداند.', 'interface OrderRepository extends JpaRepository<Order, UUID> {\n    Page<Order> findByCustomerId(String customerId, Pageable page);\n}', 'برای صفحه خالی و پر query را با دیتابیس واقعی تست کن؛ حد page size اعمال کن.', ['پس از merge کدام نمونه را باید مبنا گرفت؟', 'نمونه managed بازگشتی', 'همیشه شیء detached ورودی', 'هر دو بدون توجه به context یکسان‌اند'], 'save را برای هر تغییر ساده entity managed بی‌دلیل فراخوانی نکن.'],
[51, 'مدل رابطه‌ای باید invariant را با constraint هم محافظت کند. مقدار پول numeric، تعداد integer مثبت و رابطه با foreign key مشخص شود. soft delete یا cascade باید با سیاست حذف دامنه هماهنگ باشد.', 'sql:CREATE TABLE order_items (\n id uuid PRIMARY KEY, order_id uuid NOT NULL REFERENCES orders(id),\n quantity integer NOT NULL CHECK (quantity > 0),\n unit_price numeric(19,2) NOT NULL CHECK (unit_price >= 0)\n);', 'درج quantity صفر و order_id ناموجود را مستقیم در SQL امتحان کن؛ DB باید رد کند.', ['چرا CHECK علاوه بر validation اپ مفید است؟', 'تمام نویسنده‌های دیتابیس را زیر یک invariant می‌آورد', 'جایگزین کامل authorization است', 'نیاز به تراکنش را حذف می‌کند'], 'قواعد cross-row مانند کل موجودی با CHECK ساده یک ردیف حل نمی‌شوند.'],
[52, 'مالک رابطه JPA سمتی است که foreign key را کنترل می‌کند؛ mappedBy سمت معکوس است. متد دامنه باید دو سمت ارتباط حافظه‌ای را هماهنگ نگه دارد. cascade چرخه persistence را کنترل می‌کند، نه fetch.', 'void addItem(OrderItem item) {\n    items.add(item);\n    item.setOrder(this);\n}\n// @OneToMany(mappedBy="order", cascade=CascadeType.ALL)', 'یک Order با دو item ذخیره و در context تازه بخوان؛ foreign key و حذف item را بررسی کن.', ['mappedBy به چه چیزی اشاره می‌کند؟', 'نام فیلد رابطه در سمت مالک', 'نام جدول دیتابیس', 'نام schema پیش‌فرض PostgreSQL'], 'CascadeType.ALL را بی‌فکر روی رابطه به موجودیت مستقل مثل Product نگذار.'],
[53, 'LAZY هدف را تا زمان نیاز بارگذاری می‌کند، اما تضمین حذف query اضافی نیست. در ManyToOne پیش‌فرض JPA برابر EAGER است؛ fetch plan هر use case را صریح طراحی کن. بیرون تراکنش DTO بساز، نه رابطه lazy فعال کن.', '@ManyToOne(fetch = FetchType.LAZY, optional = false)\n@JoinColumn(name = "order_id", nullable = false)\nprivate Order order;', 'خروجی endpoint را به DTO تبدیل کن و تعداد queryها را بشمار؛ JSON نباید چرخه روابط بسازد.', ['LAZY به تنهایی N+1 را حل می‌کند؟', 'خیر؛ دسترسی در حلقه همچنان query اضافی می‌سازد', 'بله؛ همه رابطه‌ها در یک query می‌آیند', 'بله؛ entity دیگر نیاز به transaction ندارد'], 'فعال‌کردن OSIV برای پنهان‌کردن LazyInitializationException می‌تواند query را تا لایه نمایش نشت دهد.'],
[54, 'برای توسعه DB را با volume پایدار و healthcheck اجرا کن. داخل شبکه Compose نام سرویس hostname است؛ localhost در container به خودش اشاره دارد. version دیتابیس را مشخص و تغییر major را با migration مدیریت کن.', 'yaml:services:\n  db:\n    image: postgres:17\n    environment:\n      POSTGRES_DB: orders\n      POSTGRES_PASSWORD: local-only\n    volumes:\n      - db_data:/var/lib/postgresql/data\nvolumes:\n  db_data:', 'از container اپ به db:5432 وصل شو؛ پس از restart داده بماند و رمز نمونه وارد production نشود.', ['hostname دیتابیس از container اپ در Compose چیست؟', 'نام سرویس مانند db', 'همیشه localhost', 'نام پوشه سورس Java'], 'حذف volume داده را حذف می‌کند؛ قبل از عملیات پاک‌سازی backup را جدی بگیر.'],
[55, 'Persistence context یک identity map در مرز session/transaction است؛ دو find برای یک id معمولاً همان نمونه managed را می‌دهند. bulk update آن را خودکار همگام نمی‌کند و می‌تواند state قدیمی باقی بگذارد.', 'Order first = entityManager.find(Order.class, id);\nOrder second = entityManager.find(Order.class, id);\nassert first == second;\nentityManager.clear(); // objects become detached', 'پس از clear دوباره query کن؛ تفاوت هویت object و هویت ردیف را توضیح بده.', ['پس از bulk update چه ریسکی وجود دارد؟', 'ماندن entity قدیمی در persistence context', 'commit خودکار تمام contextهای جهان', 'تبدیل entityها به record immutable'], 'clear تمام تغییرات flush‌نشده را می‌تواند از پیگیری خارج کند؛ ترتیب flush و clear مهم است.'],
[56, 'N+1 یعنی یک query پایه و queryهای اضافه هنگام پیمایش روابط. EAGER الزاماً join نیست. fetch join، EntityGraph یا projection را متناسب با اندازه داده انتخاب کن؛ collection join همراه pagination خطرناک است.', '@EntityGraph(attributePaths = "items")\n@Query("select o from Order o where o.id = :id")\nOptional<Order> findWithItems(@Param("id") UUID id);', 'برای ۱ و ۲۰ سفارش تعداد SQLها را مقایسه کن؛ list API را با projection یا دو query محدود اصلاح کن.', ['آیا EAGER تضمین یک query دارد؟', 'خیر؛ ممکن است secondary select بسازد', 'بله؛ JPA تمام روابط را همیشه join می‌کند', 'بله؛ فقط برای جدول دارای index'], 'join چند collection می‌تواند حاصل‌ضرب ردیف‌ها بسازد؛ کم‌شدن query همیشه کم‌شدن هزینه نیست.'],
[57, 'Index باید الگوی WHERE و ORDER BY را پشتیبانی کند؛ هزینه نوشتن و فضا نیز دارد. ترتیب ستون‌های index مرکب مهم است. optimizer با آمار و selectivity تصمیم می‌گیرد و مجبور نیست از هر index استفاده کند.', 'sql:CREATE INDEX orders_customer_created_idx\nON orders(customer_id, created_at DESC, id DESC);', 'query سفارش‌های یک مشتری را قبل و بعد index با داده کافی توضیح و مقایسه کن.', ['چرا ممکن است sequential scan انتخاب شود؟', 'وقتی سهم بزرگی از جدول خوانده می‌شود ارزان‌تر است', 'وجود primary key تمام indexها را غیرفعال می‌کند', 'PostgreSQL index مرکب ندارد'], 'ساخت index روی هر ستون به طور مستقل جای تحلیل workload نیست.'],
[58, 'اصلاح N+1 را با شمارش query و اندازه داده ثابت اثبات کن. برای فهرست، اول صفحه شناسه‌ها را بخوان و سپس داده مورد نیاز همان صفحه را fetch کن. ترتیب نهایی را دوباره مطابق صفحه بساز.', 'sql:SELECT id FROM orders ORDER BY created_at DESC, id DESC LIMIT 20;\n-- Fetch only those IDs and map into the page order.\nSELECT * FROM order_items WHERE order_id IN (:page_ids);', 'با ۱۰۰ سفارش و چند item، صفحه ۲۰تایی را بخوان؛ تعداد query با تعداد item خطی رشد نکند.', ['برای pagination collection fetch چه رویکردی قابل کنترل‌تر است؟', 'صفحه شناسه‌ها و سپس fetch محدود همان صفحه', 'fetch تمام جدول و page در JVM', 'افزایش heap بدون بررسی SQL'], 'تست کوچک با یک سفارش، N+1 و pagination حافظه‌ای را پنهان می‌کند.'],
[59, 'JPQL بر entity و field کار می‌کند؛ SQL native بر جدول و ستون. parameter binding از injection مقدار جلوگیری می‌کند؛ نام ستون sort یا identifier را نمی‌توان مثل مقدار bind کرد، باید allowlist شود.', '@Query("select o from Order o where o.customerId = :customer")\nList<Order> findOrders(@Param("customer") String customer);', 'ورودی شامل کوتیشن را به query بده؛ query باید همان مقدار را جستجو کند و ساختار SQL عوض نشود.', ['برای value ورودی client چه رویکردی امن‌تر است؟', 'bind parameter', 'چسباندن رشته با +', 'حذف تمام فاصله‌ها از ورودی'], 'native query همیشه سریع‌تر نیست؛ portability و mapping نتیجه را هم بسنج.'],
[60, 'EXPLAIN طرح تخمینی را نشان می‌دهد؛ ANALYZE query را واقعاً اجرا می‌کند. اختلاف rows تخمینی و واقعی می‌تواند نشانه آمار نامناسب باشد. BUFFERS به تشخیص خواندن داده کمک می‌کند؛ فقط زمان نهایی را نبین.', 'sql:EXPLAIN (ANALYZE, BUFFERS)\nSELECT id FROM orders WHERE customer_id = \'c1\'\nORDER BY created_at DESC LIMIT 20;', 'estimated rows، actual rows و bufferها را ثبت کن؛ قبل و بعد index روی dataset یکسان مقایسه کن.', ['EXPLAIN ANALYZE برای UPDATE چه خطری دارد؟', 'UPDATE واقعاً اجرا می‌شود', 'فقط query را parse می‌کند و هیچ اثری ندارد', 'تمام tableها را خودکار vacuum می‌کند'], 'عملیات تغییردهنده را بی‌فکر در production با ANALYZE اجرا نکن.'],
[61, 'ACID با invariant کسب‌وکار یکی نیست؛ isolation تعیین می‌کند تراکنش‌ها چه چیزی از یکدیگر ببینند. READ COMMITTED در PostgreSQL برای هر statement snapshot تازه دارد؛ یک SELECT عادی موجودی را قفل نمی‌کند.', 'sql:BEGIN;\nSELECT available_quantity FROM inventory WHERE product_id = :id FOR UPDATE;\nUPDATE inventory SET available_quantity = available_quantity - 1 WHERE product_id = :id;\nCOMMIT;', 'در دو connection یک موجودی را رزرو کن؛ زمان انتظار lock و نتیجه نهایی را مشاهده کن.', ['SELECT عادی در READ COMMITTED برای رزرو امن کافی است؟', 'خیر؛ قفل یا update شرطی و تراکنش لازم است', 'بله؛ ACID همه invariantها را حدس می‌زند', 'بله؛ commit خودکار مانع تمام raceهاست'], 'زمان نگه‌داشتن lock را با تماس شبکه طولانی نکن.'],
[62, 'REQUIRED به تراکنش موجود می‌پیوندد؛ REQUIRES_NEW تراکنش مستقلی می‌سازد و اتصال دیگری می‌تواند بخواهد. به طور پیش‌فرض RuntimeException rollback می‌کند؛ checked exception الزاماً چنین نیست. proxy و self-invocation را لحاظ کن.', '@Transactional(rollbackFor = IOException.class)\npublic void importOrders() throws IOException {\n    saveRows();\n    readRequiredDocument();\n}', 'یک checked exception پس از insert ایجاد کن و rollback را با و بدون rollbackFor بررسی کن.', ['REQUIRES_NEW چه خصوصیتی دارد؟', 'تراکنش مستقل با commit/rollback جدا', 'همیشه بخشی از همان commit بیرونی است', 'هیچ اتصال دیتابیس نمی‌خواهد'], 'readOnly تضمین امنیتی منع تمام writeها نیست؛ قرارداد و تنظیم persistence را بشناس.'],
[63, 'Optimistic locking با @Version تعارض را هنگام write تشخیص می‌دهد؛ pessimistic locking دسترسی رقیب را منتظر می‌گذارد. انتخاب به میزان contention، زمان تراکنش و سیاست retry وابسته است.', '@Version\nprivate long version;\n// A stale update fails instead of silently overwriting the newer value.', 'دو transaction یک entity را بخوانند و تغییر دهند؛ یکی باید تعارض نسخه بگیرد و retry کل use case بررسی شود.', ['برای optimistic locking چه چیزی تعارض را آشکار می‌کند؟', 'بررسی نسخه هنگام update', 'final بودن id در DTO', 'فقط خواندن entity با findById'], 'retry یک save روی entity کهنه کافی نیست؛ داده و تصمیم دامنه دوباره خوانده شوند.'],
[64, 'Update شرطی، check و decrement را در DB اتمیک می‌کند. تعداد ردیف تغییرکرده نتیجه رزرو است. سفارش و تغییر موجودی باید در یک تراکنش باشند تا شکست مرحله بعد موجودی را برگرداند.', 'sql:UPDATE inventory SET available_quantity = available_quantity - :qty\nWHERE product_id = :id AND :qty > 0 AND available_quantity >= :qty;\n-- affected rows = 1 means reserved; 0 means not reserved.', 'با موجودی یک، دو رزرو همزمان اجرا کن؛ تنها یک update موفق باشد و هیچ عدد منفی تولید نشود.', ['از کجا موفقیت update شرطی را می‌فهمیم؟', 'تعداد ردیف‌های تغییرکرده', 'صرفاً HTTP 200 از controller', 'تعداد threadهای JVM'], 'اگر entity قبلاً managed است، bulk update نیاز به هماهنگ‌کردن context دارد.'],
[65, 'Deadlock یعنی چرخه انتظار lock؛ DB معمولاً یکی از تراکنش‌ها را قربانی می‌کند. ترتیب ثابت گرفتن lock احتمال آن را کم می‌کند، اما حذف کامل همه deadlockها را تضمین نمی‌کند. retry باید محدود و برای کل تراکنش تازه باشد.', 'var ids = request.items().stream()\n    .map(Line::productId).distinct().sorted().toList();\nfor (UUID id : ids) inventory.lockById(id);', 'دو سفارش با ترتیب معکوس دو محصول را آزمایش کن؛ با ترتیب ثابت و retry محدود رفتار را بررسی کن.', ['محل مناسب retry شکست deadlock چیست؟', 'بیرون مرز تراکنش، با تراکنش جدید و backoff', 'داخل همان transaction شکست‌خورده', 'حلقه بی‌نهایت بدون فاصله'], 'هر exception را transient فرض نکن؛ validation و خطای دسترسی retry نمی‌خواهند.'],
[66, 'Migration اجراشده immutable است؛ تغییر فایل قبلی checksum را می‌شکند. تغییر schema باید با اپ قبلی و بعدی در دوره rollout سازگار باشد. ابتدا ستون جدید را اضافه و backfill کن، بعد مصرف‌کننده‌ها را منتقل کن.', 'sql:-- V3__add_order_currency.sql\nALTER TABLE orders ADD COLUMN currency varchar(3);\nUPDATE orders SET currency = \'USD\' WHERE currency IS NULL;', 'روی DB خالی و DB دارای داده migration را اجرا کن؛ حذف ستون قدیمی را به deploy بعد موکول کن.', ['برای اصلاح migration اجراشده چه کار کنیم؟', 'migration جدید بسازیم', 'فایل قدیمی production را بی‌صدا عوض کنیم', 'جدول history را پاک کنیم تا همه دوباره اجرا شوند'], 'backfill بزرگ می‌تواند lock و بار سنگین بسازد؛ اندازه batch و انتشار تدریجی را بسنج.'],
[67, 'Pool اتصال یک حد ظرفیت برای DB است؛ بزرگ‌ترشدن آن همیشه throughput بهتر نمی‌دهد. connectionTimeout زمان انتظار اتصال است، نه timeout اجرای query. تعداد instanceها ضرب در pool size باید با ظرفیت DB سازگار باشد.', 'yaml:spring:\n  datasource:\n    hikari:\n      maximum-pool-size: 10\n      connection-timeout: 2000', 'زیر بار زمان انتظار pool، تعداد active و زمان query را اندازه بگیر؛ سقف کل اتصال همه instanceها را حساب کن.', ['connectionTimeout Hikari چه چیزی را محدود می‌کند؟', 'انتظار برای گرفتن connection از pool', 'مدت اجرای تمام SQLها', 'عمر HTTP request در مرورگر'], 'Virtual Thread ظرفیت دیتابیس و تعداد اتصال مجاز را نامحدود نمی‌کند.'],
[68, 'Batching تعداد round-trip نوشتن را کم می‌کند اما با transaction بسیار بزرگ، حافظه context رشد می‌کند. flush/clear دوره‌ای و batch size را با driver و شیوه تولید شناسه بررسی کن؛ تضمین batch را از log ببین.', 'for (int i = 0; i < rows.size(); i++) {\n    entityManager.persist(rows.get(i));\n    if ((i + 1) % 50 == 0) { entityManager.flush(); entityManager.clear(); }\n}', '۱۰۰۰ ردیف را با batch محدود وارد کن؛ مصرف heap و SQL واقعی را ثبت کن.', ['چرا در import بزرگ clear می‌کنیم؟', 'کاهش اشیای managed نگه‌داری‌شده در context', 'برای commit قطعی هر ۵۰ ردیف', 'برای حذف رکوردها از دیتابیس'], 'flush/clear به معنی commit batch نیست؛ مرز transaction را جدا طراحی کن.'],
[69, 'Data integrity را با NOT NULL، UNIQUE، FK و CHECK محافظت کن. constraint جلوی چند نویسنده را می‌گیرد؛ validation اپ فقط یک مسیر نوشتن را پوشش می‌دهد. consistency در چند سرویس نیازمند قرارداد و جبران خطاست.', 'sql:ALTER TABLE orders ADD CONSTRAINT order_total_nonnegative CHECK (total_amount >= 0);\nALTER TABLE order_items ADD CONSTRAINT order_fk FOREIGN KEY (order_id) REFERENCES orders(id);', 'درج مستقیم داده نامعتبر و مسیر API را تست کن؛ هر دو باید invariant را حفظ کنند.', ['کدام لایه از تمام نویسنده‌های مستقیم DB محافظت می‌کند؟', 'constraint دیتابیس', 'فقط decorator اعتبارسنجی controller', 'فقط schema OpenAPI'], 'constraint را جای کنترل مالکیت و authorization کاربر نگذار.'],
[70, 'بهینه‌سازی query باید از use case و اندازه خروجی آغاز شود. برای فهرست به تمام ستون‌ها و روابط entity نیاز نیست؛ projection کوچک هزینه I/O و hydration را کم می‌کند. نتیجه را با benchmark نماینده بسنج.', 'record OrderSummary(UUID id, BigDecimal total) {}\n@Query("select new com.academy.order.OrderSummary(o.id, o.totalAmount) from Order o where o.customerId=:customer")\nList<OrderSummary> summaries(@Param("customer") String customer);', 'list API را به projection تبدیل کن؛ ستون‌ها، query count و اندازه JSON را قبل/بعد ثبت کن.', ['چه داده‌ای برای list summary لازم است؟', 'فقط فیلدهای مورد نیاز قرارداد', 'تمام entityها و تمام collectionها', 'همه ستون‌ها چون projection همیشه کندتر است'], 'query سریع بدون page limit می‌تواند با رشد داده دوباره مسئله بسازد.'],
[71, 'Unique constraint تصمیم رقابت را در DB انجام می‌دهد. Upsert سیاست تعارض را صریح می‌کند؛ DO UPDATE ممکن است داده قبلی را بازنویسی کند و برای idempotency همیشه مطلوب نیست.', 'sql:INSERT INTO customers(external_id, name) VALUES (:id, :name)\nON CONFLICT (external_id) DO UPDATE SET name = EXCLUDED.name;', 'دو insert همزمان یک external_id را اجرا کن؛ مشخص کن update مجاز است یا باید conflict بدهد.', ['وجود یک SELECT پیش از INSERT جلوی duplicate را تضمین می‌کند؟', 'خیر؛ unique constraint هنوز لازم است', 'بله؛ حتی در چند connection', 'بله؛ اگر اسم متد exists باشد'], 'unique violation را در transaction شکست‌خورده نبلع؛ مرز rollback و retry را رعایت کن.'],
[72, 'Backup بدون آزمایش restore تضمین بازیابی نیست. RPO میزان داده قابل ازدست‌رفتن و RTO زمان بازیابی قابل قبول است. rollback کد با rollback schema یکی نیست؛ بسیاری تغییرها migration رو به جلو می‌خواهند.', 'bash:pg_dump -Fc -h localhost -U orders -d orders -f orders.dump\npg_restore --clean --if-exists -h localhost -U orders -d orders_restore orders.dump', 'backup را در DB جدا restore کن؛ تعداد ردیف، constraints و یک query تجاری را بررسی کن.', ['مهم‌ترین شاهد قابل استفاده‌بودن backup چیست؟', 'restore موفق و بررسی داده و رفتار', 'صرف وجود فایل با پسوند dump', 'بزرگ‌بودن اندازه فایل backup'], 'فرمان restore را روی DB مقصد واقعی بی‌برنامه اجرا نکن؛ --clean اشیای موجود را حذف می‌کند.'],
[73, 'Authentication هویت را مشخص می‌کند؛ authorization مجازبودن عمل روی منبع را. کاربر لاگین‌شده نباید سفارش مشتری دیگر را فقط با حدس id بخواند. ownership را در query یا service enforce کن.', '@PreAuthorize("isAuthenticated()")\npublic OrderResponse get(UUID id, String customerId) {\n    return repository.findByIdAndCustomerId(id, customerId)\n        .map(OrderResponse::fromEntity).orElseThrow(NotFoundException::new);\n}', 'دو کاربر با دو سفارش بساز؛ خواندن سفارش کاربر دیگر نباید داده افشا کند.', ['آیا authenticated بودن برای خواندن هر order کافی است؟', 'خیر؛ ownership یا policy دسترسی هم لازم است', 'بله؛ UUID غیرقابل حدس است', 'بله؛ اگر role نام USER داشته باشد'], 'customerId معتبر را از principal بگیر، نه از body یا query قابل جعل.'],
[74, 'SecurityFilterChain پیش از MVC درخواست را احراز و مجوزدهی می‌کند. چند chain با matcher و order انتخاب می‌شوند؛ نخستین chain منطبق مهم است. permitAll برای /api/** محافظت واقعی API را حذف می‌کند.', '@Bean\nSecurityFilterChain security(HttpSecurity http) throws Exception {\n    return http.authorizeHttpRequests(a -> a\n        .requestMatchers("/actuator/health/**").permitAll()\n        .anyRequest().authenticated()).httpBasic(Customizer.withDefaults()).build();\n}', 'برای anonymous، کاربر معتبر و مسیر health تست 401/200 بنویس؛ تمام actuatorها عمومی نباشند.', ['SecurityFilterChain معمولاً چه زمانی اجرا می‌شود؟', 'پیش از رسیدن درخواست به controller', 'فقط پس از serialization پاسخ', 'فقط اگر controller آن را دستی صدا کند'], 'CSRF را فقط با تحلیل نوع credential و client غیرفعال کن؛ stateless بودن به تنهایی کافی نیست.'],
[75, 'OAuth2 مجوز دسترسی و OIDC هویت را استاندارد می‌کنند؛ JWT فقط یک قالب token است. decode کردن Base64 احراز هویت نیست. signature، issuer، زمان اعتبار و audience مورد انتظار را بررسی کن؛ refresh token کار resource server نیست.', 'yaml:spring:\n  security:\n    oauth2:\n      resourceserver:\n        jwt:\n          issuer-uri: https://idp.example.com/issuer\n          audiences: orders-api', 'token منقضی، issuer اشتباه و audience اشتباه را تست کن؛ هیچ‌کدام نباید به endpoint برسند.', ['خواندن payload JWT بدون verification چه تضمینی دارد؟', 'هیچ تضمین اصالت یا مجوزی نمی‌دهد', 'اثبات هویت چون JSON معتبر است', 'کافی است اگر token طولانی باشد'], 'starter مناسب resource server و تنظیم chain لازم است؛ token واقعی را در log نگذار.'],
[76, 'امن‌سازی API باید policy قابل آزمون داشته باشد. روش credential را صریح انتخاب کن؛ HTTP Basic محلی برای آموزش ساده است و در انتقال واقعی TLS لازم دارد. JWT مسیر دیگری است، نه نام جدید Basic.', 'http.authorizeHttpRequests(a -> a\n    .requestMatchers(HttpMethod.GET, "/api/orders/**").hasAuthority("orders:read")\n    .requestMatchers(HttpMethod.POST, "/api/orders").hasAuthority("orders:write")\n    .anyRequest().denyAll());', 'کاربر فقط‌خواندنی را با GET موفق و POST ممنوع تست کن؛ مالکیت سفارش را نیز جدا بسنج.', ['کاربر معتبر فاقد permission معمولاً چه پاسخی می‌گیرد؟', '403', 'همیشه 401 مانند anonymous', '201 همراه warning'], 'امنیت URL به تنهایی جلوی فراخوانی داخلی نامجاز service را نمی‌گیرد.'],
[77, 'RBAC role را به مجموعه permissionها وصل می‌کند؛ method security برای محافظت مرز use case مفید است. hasRole پیشوند ROLE_ دارد، hasAuthority تطبیق مستقیم می‌خواهد. @EnableMethodSecurity را فعال کن.', '@EnableMethodSecurity\n@Configuration\nclass MethodSecurityConfig {}\n// On a Spring-managed service method:\n@PreAuthorize("hasAuthority(\'orders:write\')")\npublic UUID place(CreateOrder request) { return create(request); }', 'service را با principal فاقد permission مستقیماً در Spring test صدا بزن؛ دسترسی باید رد شود.', ['hasRole("ADMIN") پیش‌فرض دنبال چه authority است؟', 'ROLE_ADMIN', 'admin بدون توجه به حروف', 'هر authority شامل متن ADMIN'], 'self-invocation یا ساخت service با new می‌تواند proxy method security را دور بزند.'],
[78, 'Secret نباید وارد git، image layer یا log شود. environment و secret file روش تزریق‌اند، نه به‌خودی‌خود سیاست دسترسی یا rotation. دسترسی محدود، عمر کوتاه و قابلیت تعویض را طراحی کن.', 'yaml:spring:\n  datasource:\n    password: ${DB_PASSWORD}', 'رمز را از محیط تزریق کن و با جستجوی repo/image/log نبودنش را بررسی کن؛ تعویض بدون commit انجام شود.', ['حذف رمز از آخرین commit برای رفع افشا کافی است؟', 'خیر؛ باید رمز rotate و تاریخچه و دسترسی بررسی شود', 'بله؛ git نسخه قبلی را خودکار پاک می‌کند', 'بله؛ اگر فایل به .gitignore اضافه شود'], 'مقدار پیش‌فرض production برای password نگذار که نبود secret را پنهان کند.'],
[79, 'تست باید رفتار قابل مشاهده را با Arrange/Act/Assert توضیح دهد. assertion دقیق اختلاف را آشکار می‌کند؛ تستی که هیچ assertion ندارد ممکن است بدون سنجش هدف سبز شود. exception و مرزها را با داده مشخص امتحان کن.', '@Test\nvoid rejectsZeroQuantity() {\n    assertThrows(IllegalArgumentException.class, () -> new OrderLine("sku", 0));\n}', 'برای quantity منفی، صفر و مثبت تست پارامتری بنویس؛ عمداً یک باگ وارد کن و شکست تست را ببین.', ['یک assertion مفید چه چیزی را نشان می‌دهد؟', 'رفتار مورد انتظار و اختلاف واقعی', 'فقط اینکه متد اجرا شد', 'همیشه خطا را catch و تست را سبز می‌کند'], 'assert زبان Java ممکن است غیرفعال باشد؛ از assertion کتابخانه تست استفاده کن.'],
[80, 'Mockito برای کنترل مرز وابستگی است؛ منطق تحت آزمون را mock نکن. stub پاسخ لازم را تعیین می‌کند و verify فقط تعامل مهم قرارداد را می‌سنجد. over-mocking تست را به جزئیات پیاده‌سازی قفل می‌کند.', 'when(stock.reserve("sku", 2)).thenReturn(false);\nassertThrows(InsufficientStockException.class, () -> checkout.place("sku", 2));\nverify(payments, never()).charge(any());', 'شکست رزرو را تست کن؛ در این مسیر پرداخت نباید صدا زده شود.', ['چه چیزی معمولاً نباید mock شود؟', 'خود واحد دارای منطق مورد آزمون', 'یک gateway بیرونی کند', 'یک وابستگی با خطای قابل کنترل'], 'verify همه getterها به جای assertion خروجی، تست شکننده می‌سازد.'],
[81, 'Unit test سریع قواعد محلی را می‌سنجد؛ integration test مرز واقعی مثل mapping SQL را. تست end-to-end برای مسیرهای حیاتی است و به علت هزینه جای همه unitها را نمی‌گیرد.', 'text:Domain rules -> unit tests\nRepository + PostgreSQL -> integration tests\nPOST order + GET order -> a few end-to-end journeys', 'برای یک باگ mapper، یک race و یک permission، کم‌هزینه‌ترین سطح تست مؤثر را انتخاب کن.', ['تست mapping JPA را کجا بهتر می‌توان سنجید؟', 'integration با DB واقعی هدف', 'فقط mock کردن repository', 'صرفاً snapshot رنگ صفحه'], 'تعداد تست به تنهایی کیفیت را نشان نمی‌دهد؛ خطاهای مهم قابل تشخیص معیارند.'],
[82, 'OrderService باید هم نتیجه و هم invariant شکست را حفظ کند. در unit test تصمیم رزرو/پرداخت را با fake یا mock کنترل کن؛ rollback واقعی را فقط با transaction manager و DB تست کن.', 'when(inventory.reserve(sku, 2)).thenReturn(false);\nassertThrows(InsufficientStockException.class, () -> orders.place(request));\nverify(orderRepository, never()).save(any());', 'عدم ذخیره سفارش پس از شکست موجودی را unit-test کن و برگشت موجودی را integration-test کن.', ['Mock repository چه چیزی را ثابت نمی‌کند؟', 'rollback واقعی PostgreSQL', 'تعداد فراخوانی متد mock', 'انتخاب شاخه خطای منطق service'], 'unit test سبز با mock، اثبات ACID یا صحت annotationهای Spring نیست.'],
[83, 'SpringBootTest context گسترده را می‌سازد؛ برای هر تست کوچک لازم نیست. web test با MockMvc قرارداد servlet را بدون پورت واقعی می‌سنجد؛ RANDOM_PORT یک سرور واقعی محلی می‌خواهد. سطح تست را با هدف هماهنگ کن.', '@SpringBootTest\n@AutoConfigureMockMvc\nclass OrderHttpTest {\n    @Autowired MockMvc mvc;\n}', 'یک درخواست نامعتبر را با MockMvc و یک مسیر واقعی را با پورت تصادفی تست کن؛ تفاوت مرزها را بنویس.', ['MockMvc الزاماً سرور TCP واقعی اجرا می‌کند؟', 'خیر؛ زنجیره MVC را در process تست می‌کند', 'بله؛ همیشه پورت 8080 را اشغال می‌کند', 'خیر؛ حتی filterها نیز هرگز اجرا نمی‌شوند'], 'package annotationهای test را با نسخه Boot انتخاب کن؛ مهاجرت Boot می‌تواند importها را تغییر دهد.'],
[84, 'Coverage می‌گوید خط اجرا شده، نه اینکه نتیجه درست سنجیده شده است. branch coverage، assertionهای معنادار و mutation testing تصویر کامل‌تری می‌دهند. تست با ورودی نامعتبر و رقابت را فقط برای درصد حذف نکن.', 'text:Mutation: change available >= requested to available > requested\nExpected: test with available == requested must fail.', 'تست مرز برابر موجودی را بنویس و یک تغییر عمدی > را وارد کن؛ تست باید آن را بگیرد.', ['آیا ۱۰۰٪ line coverage اثبات صحت است؟', 'خیر؛ assertion و سناریوهای حساس مهم‌اند', 'بله؛ همه خطاهای منطقی حذف شده‌اند', 'بله؛ دیگر integration test لازم نیست'], 'mock کردن بیش‌ازحد می‌تواند coverage زیاد با اطمینان کم بسازد.'],
[85, 'Testcontainers دیتابیس واقعی و disposable می‌دهد؛ تست به Docker نیاز دارد. نسخه image را مشخص کن و URL/credential را پویا بگیر. H2 جایگزین معادل SQL و lockهای PostgreSQL نیست.', '@Container\nstatic PostgreSQLContainer<?> db = new PostgreSQLContainer<>("postgres:17-alpine");\n@DynamicPropertySource\nstatic void dbProperties(DynamicPropertyRegistry r) {\n    r.add("spring.datasource.url", db::getJdbcUrl);\n    r.add("spring.datasource.username", db::getUsername);\n    r.add("spring.datasource.password", db::getPassword);\n}', 'migration واقعی را روی container اجرا کن؛ query و constraint را بدون تنظیم دستی پورت تست کن.', ['برای سنجش lockهای PostgreSQL کدام بهتر است؟', 'PostgreSQL واقعی در Testcontainers', 'فقط H2 بدون مقایسه رفتار', 'Mockito برای Connection'], 'اولین دریافت image اینترنت می‌خواهد؛ اجرای آفلاین نیازمند imageهای از قبل دریافت‌شده است.'],
[86, 'Repository test باید mapping، query، constraint و fetch plan را بسنجد. flush و clear کمک می‌کند موفقیت از identity map نیاید. دیتابیس خالی و روابط چندتایی هر دو لازم‌اند.', 'repository.save(order);\nentityManager.flush();\nentityManager.clear();\nvar reloaded = repository.findWithItems(order.getId()).orElseThrow();\nassertEquals(2, reloaded.getItems().size());', 'یک سفارش با دو item ذخیره و با context تازه بخوان؛ foreign key و مبلغ دقیق حفظ شوند.', ['چرا پیش از بازخوانی clear مفید است؟', 'وادارکردن تست به خواندن مجدد از DB', 'commit کردن خودکار تراکنش', 'حذف همه جدول‌ها'], 'تست خواندن همان object حافظه‌ای ممکن است mapping خراب را پنهان کند.'],
[87, 'Contract test انتظار مصرف‌کننده از درخواست و پاسخ را در برابر provider می‌سنجد. schema لازم است اما معنای status، nullable بودن و سازگاری نام فیلدها هم اهمیت دارند.', 'json:{"id":"uuid","status":"CONFIRMED","totalAmount":12.50,"currency":"USD"}', 'برای consumer فیلدهای ضروری و وضعیت 404 را قرارداد کن؛ حذف currency باید تست را بشکند.', ['تست قرارداد بیشتر کدام ریسک را کم می‌کند؟', 'شکستن ارتباط consumer و provider پس از تغییر API', 'تمام raceهای دیتابیس', 'هر مشکل CPU و GC'], 'قرارداد را با implementation مشترک تولید نکن که هر دو همزمان یک باگ را بپذیرند.'],
[88, 'تست HTTP فقط happy path نیست: status، header، body و authorization را با داده کنترل‌شده بسنج. validation نباید order بسازد و client دیگر نباید پاسخ آن را ببیند.', 'mvc.perform(post("/api/orders")\n    .contentType(MediaType.APPLICATION_JSON)\n    .content("{\"customerId\":\"c1\",\"items\":[]}"))\n    .andExpect(status().isBadRequest());', 'مسیر ایجاد، خواندن، body نامعتبر و دسترسی کاربر دیگر را در تست‌های مستقل بساز.', ['برای request نامعتبر چه چیزی علاوه بر 400 مهم است؟', 'هیچ تغییر پایدار ناخواسته‌ای رخ ندهد', 'فقط متن دکمه مرورگر عوض شود', 'server آن را بی‌قید retry کند'], 'تست با disable کردن تمام filterها، امنیت API را نمی‌سنجد.'],
[89, 'تراکنش تست روی thread اجرای تست اعمال می‌شود؛ درخواست سرور واقعی یا task async لزوماً داخل آن نیست. rollback تست نمی‌تواند commit یک process دیگر را برگرداند. cleanup و ایزولاسیون را صریح طراحی کن.', 'text:Test thread transaction -> MockMvc may share thread\nHTTP server / executor thread -> separate transaction boundary\nUse unique fixture IDs and explicit cleanup for committed work.', 'با RANDOM_PORT یک سفارش ایجاد کن؛ پس از پایان تست بررسی کن آیا داده مانده است و cleanup اضافه کن.', ['آیا @Transactional تست، write سرور HTTP جدا را حتماً rollback می‌کند؟', 'خیر؛ مرز thread/transaction جداست', 'بله؛ نام متد test تمام DB را احاطه می‌کند', 'بله؛ اگر پورت تصادفی باشد'], 'تست موازی با پاک‌کردن سراسری جدول‌ها می‌تواند نتایج یکدیگر را خراب کند.'],
[90, 'CI باید build قابل تکرار، تست و گزارش شکست داشته باشد. dependency cache زمان را کم می‌کند اما source of truth نیست. secret و token فقط به job موردنیاز و با دسترسی حداقلی داده شوند.', 'bash:./mvnw -B verify\n# Run in a job with a Docker daemon when Testcontainers tests are enabled.\n# Publish surefire reports even when the test job fails.', 'یک تست را عمداً خراب کن؛ job باید fail و گزارش قابل خواندن تولید کند.', ['یک pipeline مطمئن با شکست تست چه می‌کند؟', 'fail می‌شود و گزارش خطا نگه می‌دارد', 'همیشه deploy می‌کند و warning چاپ می‌کند', 'تست را خودکار حذف می‌کند'], 'skipTests برای سبزکردن pipeline، آماده‌بودن انتشار را اثبات نمی‌کند.'],
[91, 'Timeout بودجه انتظار است؛ connect timeout و response timeout متفاوت‌اند. retry فقط برای شکست موقت و عملیات امن با سقف تلاش، backoff و jitter مناسب است. مجموع تلاش‌ها باید داخل deadline درخواست بماند.', 'var client = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(2)).build();\nvar request = HttpRequest.newBuilder(uri).timeout(Duration.ofSeconds(3)).GET().build();\nvar response = client.send(request, HttpResponse.BodyHandlers.ofString());', 'یک سرور آزمایشی دیرپاسخ بساز؛ timeout و قطع انتظار را مشاهده کن و POST بدون کلید را خودکار retry نکن.', ['برای retry ثبت سفارش چه چیزی حیاتی است؟', 'سیاست idempotency و بودجه محدود تلاش', 'افزایش بی‌نهایت تعداد تلاش', 'retry همه خطاهای 400'], 'Future timeout الزاماً کار زیرین یا درخواست شبکه را لغو نمی‌کند؛ cancellation را بررسی کن.'],
[92, 'Circuit breaker جلوی فشار تکراری به وابستگی خراب را می‌گیرد؛ bulkhead ظرفیت جدا می‌کند تا خرابی یک مسیر همه سرویس را نخواباند. حالت half-open با تعداد محدود درخواست بازیابی را می‌سنجد.', 'yaml:resilience4j:\n  circuitbreaker:\n    instances:\n      payment:\n        slidingWindowSize: 20\n        minimumNumberOfCalls: 10\n        failureRateThreshold: 50', 'وابستگی پرداخت را خراب کن و گذار closed/open/half-open را مشاهده کن؛ مسیر مستقل سالم بماند.', ['Bulkhead چه چیزی را جدا می‌کند؟', 'ظرفیت همزمانی یا منابع مسیرها', 'schema تمام جدول‌ها', 'کلیدهای JWT کاربران'], 'fallback نباید موفقیت پرداخت جعلی بسازد؛ degraded response باید معنای درست داشته باشد.'],
[93, 'در API، کنترل مالکیت منبع از چک role مهم‌تر هم می‌تواند باشد. شناسه غیرقابل حدس جای authorization نیست. page size، body size و مصرف منابع را محدود کن؛ URL ورودی کاربر می‌تواند ریسک SSRF بسازد.', 'repository.findByIdAndCustomerId(orderId, principal.customerId())\n    .orElseThrow(OrderNotFoundException::new);', 'با حساب A، id سفارش B را درخواست کن؛ هیچ فیلد خصوصی در response یا log افشا نشود.', ['UUID تصادفی چه چیزی را جایگزین نمی‌کند؟', 'کنترل مالکیت و authorization', 'شناسه یکتا در قرارداد', 'امکان lookup سفارش با id'], 'اعتبارسنجی syntactic ورودی با مجوز دسترسی به همان داده متفاوت است.'],
[94, 'در Resilience4j، name باید به configuration همان instance اشاره کند و AOP dependency فعال باشد. exceptionهای تجاری را بی‌دلیل failure زیرساخت حساب نکن. decorator باید مرز درست فراخوانی بیرونی را احاطه کند.', '@CircuitBreaker(name = "payment")\npublic Receipt charge(PaymentRequest request) {\n    return paymentClient.charge(request);\n}', 'سرور پرداخت را با 503 و سپس بازیابی آزمایش کن؛ validation error نباید breaker را بی‌دلیل باز کند.', ['کدام failure برای breaker وابستگی پرداخت مرتبط‌تر است؟', 'timeout و 503 همان وابستگی', 'خطای validation مشتری پیش از تماس شبکه', '404 یک صفحه نامرتبط سایت'], 'self-invocation advice را دور می‌زند؛ فقط وجود annotation را تست نکن.'],
[95, 'Rate limit نرخ درخواست را محدود می‌کند؛ concurrency limit تعداد کارهای درحال‌اجرا را. کلید محدودیت باید مناسب کاربر/tenant و مدل تهدید باشد. در چند instance، limiter حافظه‌ای سقف سراسری نمی‌دهد.', 'http:HTTP/1.1 429 Too Many Requests\nRetry-After: 10\nContent-Type: application/problem+json\n\n{"title":"Rate limit exceeded","status":429}', 'دو کاربر را جدا محدود کن و دو instance را آزمایش کن؛ پاسخ 429 راه retry منطقی بدهد.', ['Limiter محلی با دو instance چه تغییری می‌کند؟', 'ممکن است ظرفیت مؤثر چندبرابر شود', 'همیشه سقف سراسری دقیق می‌ماند', 'خودکار داده را در Redis ذخیره می‌کند'], 'X-Forwarded-For بدون مرز proxy مورد اعتماد می‌تواند قابل جعل باشد.'],
[96, 'اسکن dependency نشانه‌های advisory را پیدا می‌کند، نه اثبات exploitability یا نبود همه ریسک‌ها. dependency مستقیم و transitive، نسخه قفل‌شده و image پایه را بررسی کن. اصلاح را با تست رفتار و build همراه کن.', 'bash:./mvnw dependency:tree\npnpm audit --prod\n# Review official advisories and upgrade the actual resolved dependency.', 'یک advisory واقعی را با نسخه resolved تطبیق بده و تصمیم patch را همراه تست و منبع ثبت کن.', ['پس از اسکن بدون هشدار چه نتیجه‌ای مجاز است؟', 'در آن پایگاه و زمان هشدار شناخته‌شده‌ای پیدا نشد', 'اپ برای همیشه بدون آسیب‌پذیری است', 'دیگر authentication و authorization لازم نیست'], 'افزودن exception دائمی برای سبزشدن گزارش، ریسک را برطرف نمی‌کند.'],
[97, 'Exchange پیام را براساس نوع و binding به queue هدایت می‌کند؛ consumer از queue می‌خواند. direct تطبیق دقیق routing key و topic الگوی قطعه‌بندی‌شده دارد. durable بودن تعریف با پایداری هر پیام یکی نیست.', 'text:Producer -> topic exchange orders\nBinding: order.created -> inventory-events queue\nConsumer <- inventory-events', 'دو queue با binding متفاوت بساز؛ یک event باید فقط به صف‌های منطبق برسد.', ['Consumer معمولاً از کجا پیام می‌خواند؟', 'Queue', 'مستقیماً از routing key بدون queue', 'از جدول metadata exchange'], 'exchange بدون binding مناسب می‌تواند پیام unroutable بسازد؛ برگشت آن را بررسی کن.'],
[98, 'تأیید publisher یعنی broker پیام را پذیرفته؛ به معنی پردازش consumer نیست. consumer باید پس از موفقیت اثر محلی ack کند. برای پیام unroutable، mandatory و return handling را متناسب پیکربندی کن.', 'template.convertAndSend("orders", "order.created", event);\n// Configure publisher confirms and returned-message handling separately.\n// Ack consumer only after its durable transaction commits.', 'binding را حذف کن و رفتار publish را مشاهده کن؛ خطا نباید بی‌صدا ناپدید شود.', ['Publisher confirm موفق چه چیزی را اثبات نمی‌کند؟', 'اجرای موفق منطق consumer', 'پذیرش publish طبق semantics broker', 'رسیدن تأیید به publisher'], 'ارسال async بدون مشاهده confirm به معنی تحویل تضمینی نیست.'],
[99, 'At-least-once یعنی duplicate ممکن است. اگر consumer پس از commit و پیش از ack قطع شود، پیام دوباره تحویل می‌شود. اثر تجاری باید با eventId و constraint یکتا idempotent شود.', 'text:1. Receive event\n2. Begin DB transaction\n3. Claim eventId and apply business change\n4. Commit\n5. Ack', 'consumer را پس از commit و قبل از ack متوقف کن؛ redelivery نباید دوباره موجودی را تغییر دهد.', ['چرا پیام بعد از commit ممکن است تکرار شود؟', 'ack هنوز به broker نرسیده است', 'commit به معنی حذف همه queueهاست', 'RabbitMQ فقط exactly-once دارد'], 'ack قبل از commit ریسک گم‌شدن اثر را در crash بالا می‌برد.'],
[100, 'Event تجاری باید شناسه، نوع، زمان و نسخه schema داشته باشد. انتشار مستقیم بعد از commit پنجره گم‌شدن پیام دارد و انتشار قبل از commit می‌تواند رویداد سفارش rollback‌شده بسازد؛ outbox این مرز را هماهنگ می‌کند.', 'json:{"eventId":"unique-id","type":"OrderCreated","version":1,"occurredAt":"2026-01-01T00:00:00Z","data":{"orderId":"order-id"}}', 'payload را serialize و deserialize کن؛ producer نباید entity کامل و اطلاعات حساس مشتری را منتشر کند.', ['چرا OrderCreated را از entity JPA کامل نسازیم؟', 'قرارداد event باید مستقل و حداقلی باشد', 'JSON هیچ entity را serialize نمی‌کند', 'event نباید هیچ شناسه‌ای داشته باشد'], 'نام event باید واقعیت رخ‌داده را بگوید، نه فرمانی که هنوز ممکن است شکست بخورد.'],
[101, 'Retry بی‌نهایت یک poison message می‌تواند صف را قفل یا overload کند. تعداد تلاش، backoff و DLQ مشخص کن؛ پیام‌های validation دائمی معمولاً retry یکسان نمی‌خواهند. replay باید با کنترل و idempotency باشد.', 'text:main queue -> failure classification\ntransient -> delayed retry with bounded attempts\npermanent / exhausted -> dead-letter queue + alert', 'یک payload خراب و یک timeout موقت بساز؛ اولی به DLQ و دومی پس از بازیابی موفق شود.', ['پیام با schema نامعتبر معمولاً چه می‌خواهد؟', 'قرنطینه و بررسی، نه retry بی‌پایان', 'retry هر میلی‌ثانیه تا همیشه', 'ack و فراموشی بدون مشاهده‌پذیری'], 'redelivery فوری بدون تأخیر می‌تواند حلقه داغ مصرف CPU بسازد.'],
[102, 'RabbitMQ محلی با volume و healthcheck تکرارپذیرتر است. credential نمونه فقط برای توسعه است و پورت management نباید بی‌دلیل عمومی باشد. readiness اپ را با رفتار واقعی اتصال و retry راه‌اندازی بسنج.', 'yaml:services:\n  rabbitmq:\n    image: rabbitmq:4-management\n    ports:\n      - "127.0.0.1:15672:15672"\n    volumes:\n      - rabbit_data:/var/lib/rabbitmq\nvolumes:\n  rabbit_data:', 'broker را restart کن و باقی‌ماندن queue durable و پیام persistent را جدا بررسی کن.', ['durable queue به تنهایی تضمین پایداری همه پیام‌هاست؟', 'خیر؛ persistence پیام و confirm هم مهم‌اند', 'بله؛ حتی پیام transient بدون confirm', 'فقط نام queue باید durable باشد'], 'depends_on بدون health و سیاست reconnect به تنهایی آماده‌بودن broker را تضمین نمی‌کند.'],
[103, 'Outbox رکورد event را در همان تراکنش تغییر دامنه ذخیره می‌کند. relay بعداً آن را به broker می‌فرستد. فاصله publish موفق و علامت‌گذاری sent هنوز duplicate می‌سازد؛ consumer باید idempotent باشد.', '@Transactional\npublic void confirm(Order order) {\n    order.confirm();\n    orders.save(order);\n    outbox.save(OrderCreated.from(order));\n}', 'بین ذخیره order و outbox خطا ایجاد کن؛ هر دو rollback شوند. سپس relay را بعد از publish قطع کن.', ['Outbox کدام تضمین را به تنهایی نمی‌دهد؟', 'پردازش exactly-once در consumer', 'ثبت اتمیک تغییر دامنه و رکورد event در یک DB', 'قابلیت ارسال مجدد رکوردهای ارسال‌نشده'], 'حذف رکورد outbox قبل از تأیید publish می‌تواند event را گم کند.'],
[104, 'Dedup باید همراه اثر تجاری در یک transaction commit شود. SELECT exists به تنهایی در رقابت کافی نیست؛ unique key روی consumer و eventId claim را اتمیک می‌کند. مدت نگه‌داری dedup با پنجره replay سازگار باشد.', 'sql:INSERT INTO processed_events(consumer_name,event_id)\nVALUES (:consumer,:event) ON CONFLICT DO NOTHING\nRETURNING event_id;\n-- Apply business effect only when a row was inserted, in the same transaction.', 'دو consumer همزمان یک eventId را بگیرند؛ دقیقاً یک اثر DB ثبت شود.', ['کلید dedup مناسب‌تر چیست؟', 'ترکیب consumer و eventId', 'زمان دریافت پیام با دقت ثانیه', 'نام thread مصرف‌کننده'], 'ذخیره dedup در Redis و اثر در DB بدون هماهنگی می‌تواند crash gap بسازد.'],
[105, 'Eventual consistency یعنی replica یا read model می‌تواند موقتاً عقب باشد. زمان همگرایی، وضعیت pending و راه reconciliation را مشخص کن. به کاربر قبل از تأیید نهایی پرداخت، success قطعی نده.', 'json:{"orderId":"id","status":"PENDING_PAYMENT","paymentStatus":"PENDING"}', 'تاخیر event پرداخت را شبیه‌سازی کن؛ UI/API باید pending درست نشان دهد و بعد همگرا شود.', ['Read model عقب‌افتاده چه نیاز UX دارد؟', 'نمایش وضعیت موقت و راه پیگیری معنادار', 'نمایش قطعی موفقیت قبل از نتیجه', 'فرض اینکه همه replicaها همزمان‌اند'], 'تاخیر نامحدود را صرفاً eventual ننام؛ backlog و زمان همگرایی باید پایش شوند.'],
[106, 'Relay چند worker باید رکوردها را بدون انتشار همزمان غیرضروری claim کند. SKIP LOCKED ابزار تقسیم کار است، نه تضمین exactly-once. failure و retry هر رکورد را قابل مشاهده نگه دار.', 'sql:SELECT id, payload FROM outbox_events\nWHERE published_at IS NULL ORDER BY created_at\nFOR UPDATE SKIP LOCKED LIMIT 50;', 'دو relay اجرا کن؛ رکوردها پیش بروند و crash یک worker باعث گم‌شدن event نشود.', ['SKIP LOCKED چه کاری می‌کند؟', 'ردشدن از ردیف‌های قفل‌شده برای تقسیم کار', 'تأیید پردازش consumer', 'commit خودکار broker و DB با هم'], 'قفل DB را در تماس شبکه طولانی نگه ندار؛ claim/lease و چرخه retry را آگاهانه طراحی کن.'],
[107, 'Schema event قرارداد بلندعمر است. فیلد جدید اختیاری با default معقول معمولاً سازگارتر است؛ تغییر نوع یا معنای فیلد قدیمی breaking است. producer و consumer مستقل deploy می‌شوند.', 'json:{"eventId":"e1","type":"OrderCreated","version":2,"data":{"orderId":"o1","currency":"USD","total":"12.50"}}', 'consumer قدیمی را با event دارای فیلد اضافی تست کن؛ برای تغییر معنای amount نسخه و migration تعریف کن.', ['کدام تغییر ریسک breaking بیشتری دارد؟', 'تغییر معنای amount از واحد اصلی به واحد خرد بدون اعلام', 'افزودن فیلد اختیاری که consumer می‌تواند نادیده بگیرد', 'افزودن مستندات بدون تغییر payload'], 'افزودن version بدون handler و سیاست سازگاری مشکل را حل نمی‌کند.'],
[108, 'Queue depth به تنهایی کافی نیست؛ سن قدیمی‌ترین پیام، نرخ publish/ack، unacked و redelivery را کنار هم ببین. backlog رو به رشد با consumer ظاهراً روشن هم رخ می‌دهد. هشدار باید به اثر کاربر وصل باشد.', 'text:Monitor: oldest_message_age, ready, unacked, publish_rate, ack_rate\nInvestigate: rising age + ack_rate below publish_rate\nCheck: consumer failures, DB latency, poison messages', 'consumer را کند کن؛ قبل از رشد شدید خطای کاربر، backlog age و نرخ ack را ثبت کن.', ['کدام شاخص برای تأخیر پردازش صف مفیدتر است؟', 'سن قدیمی‌ترین پیام همراه نرخ‌ها', 'فقط تعداد processهای Java', 'صرفاً روشن‌بودن management UI'], 'purge صف راه درمان backlog بدون بررسی اثر تجاری نیست.'],
[109, 'Redis فقط map رشته‌ای نیست: hash برای fieldها، set برای یکتایی و sorted set برای رتبه‌بندی مناسب‌اند. عملیات یک فرمان اتمیک است؛ چند فرمان جدا لزوماً یک تصمیم اتمیک نیستند.', 'bash:redis-cli SET product:1 \'{"name":"book"}\' EX 60\nredis-cli GET product:1\nredis-cli TTL product:1', 'برای cache محصول TTL بگذار؛ نبود key و نبود محصول را از هم تفکیک کن.', ['دو فرمان GET و SET جدا چه تضمینی ندارند؟', 'اتمیک‌بودن تصمیم read-modify-write', 'امکان ذخیره رشته', 'امکان انقضای key'], 'داده حساس را بدون سیاست دسترسی، TTL و حفاظت کانال وارد cache نکن.'],
[110, 'Spring Cache abstraction سیاست ذخیره را پشت annotation می‌برد؛ backend و cache manager هنوز باید درست پیکربندی شوند. key باید تمام ورودی‌های مؤثر مثل tenant را شامل شود. self-invocation می‌تواند cache advice را دور بزند.', '@Cacheable(cacheNames="products", key="#tenant + \':\' + #id")\npublic ProductView find(String tenant, UUID id) {\n    return repository.load(tenant, id);\n}', 'دو tenant با id مشابه را تست کن؛ خروجی cache نباید میان مشتری‌ها نشت کند.', ['چه ورودی‌ای باید در cache key باشد؟', 'تمام ورودی‌های مؤثر بر نتیجه از جمله tenant', 'فقط نام متد برای همه درخواست‌ها', 'شناسه thread برای reuse بیشتر'], 'cache را جای authorization نگذار؛ هر hit همچنان باید به درخواست مجاز تعلق داشته باشد.'],
[111, 'در cache-aside ابتدا cache خوانده و در miss، DB بارگذاری می‌شود. پس از write سیاست invalidation لازم است؛ race میان خواننده و نویسنده می‌تواند مقدار قدیمی برگرداند. TTL فقط عمر خطا را محدود می‌کند.', 'text:Read: cache hit -> return; miss -> load DB -> cache with TTL\nWrite: commit DB -> invalidate affected keys\nDefine acceptable staleness and recovery when invalidation fails.', 'write محصول و read همزمان را شبیه‌سازی کن؛ پنجره stale و راه کاهش آن را توضیح بده.', ['TTL چه چیزی را تضمین نمی‌کند؟', 'fresh بودن لحظه‌ای داده پس از هر write', 'انقضای خودکار key پس از مدت تنظیم‌شده', 'امکان محدودکردن عمر cache'], 'برای موجودی مالی یا مجوز دسترسی، tolerance داده stale را صریح و محتاطانه انتخاب کن.'],
[112, 'محصول خواندنی و کم‌تغییر گزینه مناسب cache است؛ قیمت نهایی سفارش باید هنگام تصمیم تجاری از منبع معتبر تعیین شود. DTO cache‌شده را از entity و session JPA جدا نگه دار.', '@Cacheable("productViews")\npublic ProductView find(UUID id) { return products.loadView(id); }\n@CacheEvict(cacheNames="productViews", key="#id")\npublic void update(UUID id, UpdateProduct command) { products.update(id, command); }', 'دو read پیاپی را با شمارش DB call و سپس update/evict بررسی کن؛ خطای transaction را هم تست کن.', ['چه چیزی برای cache مناسب‌تر است؟', 'DTO محصول با سیاست انقضا و invalidation مشخص', 'Entity managed مشترک میان threadها', 'نتیجه authorization همه کاربران با key یکسان'], 'ترتیب commit و eviction مهم است؛ eviction پیش از commit می‌تواند race ایجاد کند.'],
[113, 'انقضای همزمان key محبوب می‌تواند stampede بسازد. jitter در TTL، single-flight محدود و stale-while-revalidate در صورت پذیرش دامنه بار را کم می‌کنند. lock cache باید lease و timeout داشته باشد.', 'text:base TTL = 60 seconds\nactual TTL = 60 + random(0..15) seconds\nOn hot miss: coordinate one loader; bound waiting and fallback.', 'با چند درخواست همزمان روی key منقضی، تعداد load DB را اندازه بگیر و با single-flight مقایسه کن.', ['هدف jitter در TTL چیست؟', 'پخش‌کردن زمان انقضا و کاهش موج همزمان', 'دقیق‌ترکردن قیمت مالی', 'تضمین durability Redis'], 'lock بدون انقضا یا انتظار نامحدود می‌تواند مشکل stampede را به توقف تبدیل کند.'],
[114, 'RDB snapshot و AOF سیاست‌های متفاوت persistence دارند و trade-off هزینه/بازیابی می‌سازند. cache بودن با datastore بودن فرق دارد؛ اگر Redis منبع حقیقت است، loss budget و backup ضروری‌تر می‌شود.', 'bash:redis-cli INFO persistence\nredis-cli INFO memory\nredis-cli PING', 'restart کنترل‌شده Redis را آزمایش و داده باقی‌مانده را بررسی کن؛ برای cache miss مسیر DB سالم بماند.', ['آیا PING موفق سلامت کل کاربرد Redis را اثبات می‌کند؟', 'خیر؛ حافظه، eviction و persistence هم مهم‌اند', 'بله؛ خطای عملیاتی دیگری ممکن نیست', 'بله؛ تمام keyها قطعاً durable شده‌اند'], 'maxmemory و eviction را با نقش Redis انتخاب کن؛ حذف key قفل یا dedup می‌تواند اثر تجاری داشته باشد.'],
[115, 'CompletableFuture ترکیب نتیجه async را بیان می‌کند؛ thenApply تبدیل همگام و thenCompose تخت‌کردن async تو‌در‌تو است. executor پیش‌فرض برای blocking I/O الزاماً مناسب نیست. خطا و timeout باید مسیر مشخص داشته باشند.', 'CompletableFuture<Product> product = loadProduct(id);\nCompletableFuture<Quote> quote = product.thenCompose(this::loadQuote)\n    .orTimeout(2, TimeUnit.SECONDS);', 'ترکیب دو مرحله async را با شکست مرحله دوم تست کن؛ exception نباید ناپدید شود.', ['برای متدی که خودش Future می‌دهد کدام مناسب‌تر است؟', 'thenCompose', 'thenApply و رهاکردن Future داخلی', 'join روی event loop بدون ملاحظه'], 'orTimeout الزاماً عملیات زیرین را متوقف نمی‌کند؛ cancellation را جدا طراحی کن.'],
[116, 'Virtual Thread برای همزمانی زیادِ کار منتظر I/O است، نه سریع‌ترکردن محاسبه CPU. تعداد connection و ظرفیت سرویس پایین‌دست همچنان محدود است. در Java 25، محدودیت pinning با synchronized نسبت به JDK 21 تغییر کرده؛ native blocking هنوز نیازمند بررسی است.', 'try (var executor = Executors.newVirtualThreadPerTaskExecutor()) {\n    var result = executor.submit(() -> blockingClient.load(id));\n    System.out.println(result.get());\n}', 'یک بار I/O و یک بار CPU را با baseline یکسان مقایسه کن؛ throughput و p95 را جدا ثبت کن.', ['Virtual Thread چه چیزی را بیشتر هدف می‌گیرد؟', 'همزمانی زیاد در کارهای منتظر I/O', 'افزایش سرعت هر محاسبه CPU', 'نامحدودکردن ظرفیت connection دیتابیس'], 'برای هر Virtual Thread یک اتصال DB دائمی رزرو نکن؛ backpressure را حفظ کن.'],
[117, 'صف نامحدود overload را به تاخیر و مصرف حافظه تبدیل می‌کند. backpressure یعنی سرعت ورودی با ظرفیت هماهنگ شود؛ صف محدود، timeout و رد کنترل‌شده ابزارهای آن‌اند. از ظرفیت‌سازی بدون سنجش latency پرهیز کن.', 'var pool = new ThreadPoolExecutor(4, 4, 0, TimeUnit.SECONDS,\n    new ArrayBlockingQueue<>(100), new ThreadPoolExecutor.AbortPolicy());', 'با نرخ ورودی بالاتر از پردازش بار بده؛ صف نباید بی‌حد رشد کند و ردشدن قابل مشاهده باشد.', ['صف نامحدود هنگام overload چه ریسکی دارد؟', 'رشد حافظه و latency بدون حد', 'حذف نیاز به rejection policy', 'افزایش نامحدود توان CPU'], 'CallerRunsPolicy روی thread حساس مانند event loop می‌تواند توقف نامناسب بسازد.'],
[118, 'پذیرش کار async با تکمیل موفق آن فرق دارد. API می‌تواند 202 و شناسه job بدهد؛ وضعیت پردازش باید پایدار و قابل پیگیری باشد. @Async خودبه‌خود transaction caller یا context امنیتی را منتقل نمی‌کند.', 'http:HTTP/1.1 202 Accepted\nLocation: /api/jobs/j1\nContent-Type: application/json\n\n{"jobId":"j1","status":"QUEUED"}', 'پس از پاسخ 202، worker را restart کن؛ کار پذیرفته‌شده نباید در صف حافظه‌ای گم شود.', ['202 چه چیزی را اعلام می‌کند؟', 'پذیرش برای پردازش، نه تضمین تکمیل', 'اتمام قطعی همه مراحل سفارش', 'rollback خودکار پس از پاسخ'], 'fire-and-forget حافظه‌ای برای کار تجاری مهم، دوام لازم را ندارد.'],
[119, 'اندازه pool از CPU، زمان انتظار، latency هدف و ظرفیت وابستگی‌ها اثر می‌گیرد. فرمول‌های ساده نقطه شروع‌اند، نه نسخه قطعی. برای CPU-bound نزدیک تعداد هسته و برای I/O با محدودیت downstream اندازه‌گیری کن.', 'text:Measure: active workers, queue length, rejection rate, p95 latency\nBound: DB connections and external-service concurrency\nTune one setting at a time under a representative workload.', 'با poolهای ۴، ۸ و ۱۶ یک workload ثابت اجرا کن؛ knee point را از latency و throughput پیدا کن.', ['افزایش pool چه زمانی می‌تواند بدتر کند؟', 'وقتی رقابت CPU یا فشار downstream بیشتر شود', 'هرگز؛ thread بیشتر همیشه بهتر است', 'فقط وقتی زبان JavaScript باشد'], 'میانگین latency به تنهایی tail latency و صف انتظار را پنهان می‌کند.'],
[120, 'Load test باید هدف، داده، نرخ ورودی و معیار شکست داشته باشد. warmup و steady state را جدا کن؛ p95/p99 و error rate مهم‌تر از فقط میانگین‌اند. request موفق با کار درست تجاری یکسان نیست.', 'javascript:import http from "k6/http";\nexport const options = { vus: 10, duration: "30s", thresholds: { http_req_failed: ["rate<0.01"] } };\nexport default function () { http.get("http://localhost:8080/actuator/health"); }', 'این baseline سلامت را اجرا کن؛ سپس سناریوی ثبت سفارش با داده مستقل و بررسی نتیجه تجاری اضافه کن.', ['چرا فقط میانگین latency کافی نیست؟', 'تاخیرهای دنباله و تجربه کاربران کند را پنهان می‌کند', 'میانگین هیچ‌وقت قابل محاسبه نیست', 'p95 همیشه از تمام timeoutها کمتر است'], 'هیچ عدد کارایی را بدون سخت‌افزار، dataset و روش تست به عنوان تضمین درس ثبت نکن.'],
[121, 'CAP درباره رفتار هنگام partition شبکه است: نمی‌توان هم پاسخ‌گویی همه گره‌های سالم و هم linearizability را همواره حفظ کرد. consistency در CAP با حرف C در ACID یکی نیست. برای هر operation سیاست read/write و داده stale را جدا انتخاب کن.', 'text:Inventory reservation during partition:\nOption A: reject/queue writes without authoritative quorum\nOption B: accept risk with an explicit reconciliation policy', 'برای رزرو موجودی و مشاهده کاتالوگ دو تصمیم متفاوت هنگام partition بنویس و دلیل تجاری بده.', ['CAP چه زمانی trade-off مشخصی تحمیل می‌کند؟', 'هنگام partition شبکه', 'در هر حلقه for داخل JVM', 'فقط زمانی که جدول هیچ index ندارد'], 'برچسب AP یا CP را بدون مدل operation و failure به کل محصول نچسبان.'],
[122, 'مرز سرویس بهتر است حول مسئولیت دامنه و مالکیت داده باشد. جداکردن deployment بدون جداکردن coupling می‌تواند distributed monolith بسازد. ابتدا مرز ماژول را در یک process آزمایش کن.', 'text:Orders owns: order state and order history\nInventory owns: stock and reservations\nCommunication: explicit commands/events; no cross-service table writes', 'وابستگی Orders و Inventory را رسم کن؛ یک write مستقیم به جدول مالک دیگر را به قرارداد تبدیل کن.', ['نشانه مرز سرویس ناسالم چیست؟', 'نیاز به deploy همزمان همه سرویس‌ها برای هر تغییر کوچک', 'قرارداد روشن و مالکیت داده مستقل', 'تست مستقل هر use case'], 'تعداد تیم، مهارت عملیات و نیاز consistency در انتخاب microservice مهم‌اند.'],
[123, 'Saga چند تراکنش محلی را با فرمان و جبران هماهنگ می‌کند. compensation rollback فیزیکی زمان نیست؛ یک عمل تجاری جدید است و ممکن است شکست بخورد. هر مرحله باید idempotent و قابل پیگیری باشد.', 'text:Reserve stock -> Authorize payment -> Confirm order\nOn payment failure -> Release reservation\nOn release failure -> Retry compensation + alert', 'شکست پرداخت و شکست جبران را شبیه‌سازی کن؛ state machine و اقدام عملیاتی را مشخص کن.', ['Compensation چه چیزی نیست؟', 'rollback اتمیک و فوری تمام سیستم‌های بیرونی', 'عمل تجاری برای خنثی‌کردن اثر مرحله قبلی', 'مرحله‌ای که خودش هم ممکن است retry بخواهد'], 'بدون ثبت پایدار state، restart coordinator می‌تواند workflow را گم کند.'],
[124, 'Workflow سفارش باید stateهای مجاز و transitionها را روشن کند. رخداد دیررس و تکراری نباید سفارش لغوشده را دوباره تأیید کند. timeout، expiry رزرو و reconciliation بخشی از طراحی‌اند.', 'text:NEW -> RESERVED -> PAYMENT_AUTHORIZED -> CONFIRMED\nRESERVED -> CANCELLED (timeout/payment failure)\nCONFIRMED -X-> RESERVED', 'event پرداخت دیررس را پس از cancellation اعمال کن؛ transition نامجاز رد و برای بررسی ثبت شود.', ['برای event دیررس پس از لغو سفارش چه نیاز داریم؟', 'کنترل state و سیاست جبران/بررسی', 'تأیید بی‌قید سفارش چون event معتبر است', 'حذف تمام تاریخچه workflow'], 'ترتیب دریافت پیام را همان ترتیب واقعی رخدادها فرض نکن.'],
[125, 'Idempotency توزیع‌شده به ذخیره پایدار و scope روشن نیاز دارد. retry از gateway، queue و client می‌تواند همزمان برسد. کلید عملیات با payload fingerprint و نتیجه ثبت شود و lease منقضی قابل بازیابی باشد.', 'sql:CREATE UNIQUE INDEX operation_key ON operations(tenant_id, operation_type, idempotency_key);', 'دو instance و سه منبع retry را شبیه‌سازی کن؛ یک اثر تجاری و پاسخ قابل replay داشته باش.', ['کلید سراسری بدون tenant چه ریسکی دارد؟', 'تعارض یا افشای نتیجه بین مشتری‌ها', 'تضمین بهتر authorization', 'حذف نیاز به ذخیره نتیجه'], 'distributed lock به تنهایی رکورد نتیجه و اتمیک‌بودن side effect را تضمین نمی‌کند.'],
[126, 'Timeout یعنی نتیجه نامعلوم است، نه لزوماً شکست عملیات. server ممکن است commit کرده ولی پاسخ گم شده باشد. طراحی recovery باید با شناسه عملیات امکان پرس‌وجو و replay امن بدهد.', 'text:Client sends POST with key k1\nServer commits -> response connection breaks\nClient retries k1 -> returns recorded result, no second order', 'اتصال را بعد از commit قطع کن؛ client باید با همان کلید نتیجه قبلی را بازیابی کند.', ['پس از timeout پاسخ POST چه چیزی را می‌دانیم؟', 'نتیجه ممکن است نامعلوم باشد', 'قطعاً هیچ write رخ نداده', 'قطعاً باید با کلید تازه retry کنیم'], 'آشفتگی شبکه را با سناریوی کنترل‌شده تست کن؛ دوباره‌کاری مالی پیامد واقعی دارد.'],
[127, 'گلوگاه با افزایش بار جابه‌جا می‌شود؛ بهینه‌سازی بخش غیرغالب سود محدودی دارد. throughput، utilization و زمان انتظار را کنار هم ببین. scaling اپ وقتی DB اشباع است ممکن است وضعیت را بدتر کند.', 'text:Request time = queue wait + CPU + DB wait + external I/O\nMeasure the largest component before changing resources.', 'برای یک endpoint breakdown زمان بساز؛ فقط بزرگ‌ترین مؤلفه را تغییر بده و دوباره اندازه بگیر.', ['وقتی DB اشباع است افزودن instance اپ چه ریسکی دارد؟', 'اتصال و فشار بیشتر روی همان گلوگاه', 'حل قطعی مشکل با CPU بیشتر اپ', 'حذف خودکار lockهای DB'], 'بهبود microbenchmark را بدون بار واقعی به بهبود end-to-end تعمیم نده.'],
[128, 'سرویس stateless داده حیاتی session را در حافظه یک instance نگه نمی‌دارد؛ این به معنی بدون state بودن کل سیستم نیست. load balancer با health/readiness ترافیک را هدایت می‌کند و drain انتشار را امن‌تر می‌سازد.', 'text:Client -> load balancer -> app A / app B\nDurable state -> database\nShared session if required -> explicit shared store', 'در میانه چند درخواست instance را عوض کن؛ کاربر نباید سفارش یا session لازم را از دست بدهد.', ['stateless service یعنی چه؟', 'عدم وابستگی correctness درخواست به حافظه همان instance', 'نبود هیچ دیتابیس در کل سیستم', 'اجبار به JWT برای هر کاربرد'], 'sticky session مشکل را پنهان می‌کند اما fault tolerance داده محلی را ایجاد نمی‌کند.'],
[129, 'Trade-off باید با requirement قابل سنجش شروع شود: latency، consistency، هزینه یا سادگی عملیات. معماری «بهترین مطلق» ندارد. گزینه ساده‌تر را تا وقتی constraint واقعی نقض نشده جدی بگیر.', 'text:Decision: modular monolith initially\nDrivers: one team, shared transactions, low operational budget\nRevisit: independent scaling or team ownership becomes necessary', 'برای یک تیم سه‌نفره monolith و microservices را با سه معیار مقایسه و یک trigger بازنگری تعیین کن.', ['دلیل معتبر انتخاب ابزار معماری چیست؟', 'پاسخ به constraint و trade-off مستند', 'فقط محبوب‌بودن در شبکه اجتماعی', 'داشتن تعداد سرویس بیشتر از رقیب'], 'پیچیدگی operational را هزینه بیرونیِ نامرئی فرض نکن.'],
[130, 'Marketplace چند مسئله مستقل دارد: catalog خواندنی، سفارش با invariant مالی و جستجوی eventual. مسیر critical خرید را ساده نگه دار و read model را با منبع حقیقت اشتباه نگیر.', 'text:Catalog -> product read model\nCheckout -> order + inventory reservation\nSearch index <- asynchronous product events\nPayments -> explicit authorization/capture workflow', 'مسیر خرید، failure پرداخت و تاخیر search را رسم کن؛ برای هرکدام consistency مورد نیاز را بنویس.', ['آیا search index منبع نهایی موجودی رزروشدنی است؟', 'معمولاً نه؛ رزرو به منبع authoritative نیاز دارد', 'بله؛ چون سریع‌تر است', 'بله؛ اگر نتیجه cache شده باشد'], 'قبل از طراحی برای میلیون‌ها کاربر، load target و ظرفیت واقعی را مشخص کن.'],
[131, 'Replication برای دسترس‌پذیری و خواندن مفید است اما replica lag دارد. Partitioning داده را به بخش‌ها تقسیم می‌کند؛ sharding میان گره‌ها هزینه join و transaction را بالا می‌برد. key انتخابی باید با queryها و توزیع بار سازگار باشد.', 'text:Write -> primary\nImmediate read-your-write -> primary or consistency-aware routing\nLag-tolerant reporting -> replica', 'بلافاصله پس از write از replica عقب‌افتاده بخوان؛ سیاست read-your-write را پیشنهاد بده.', ['خواندن فوری از replica async چه ریسکی دارد؟', 'ندیدن آخرین write به علت lag', 'تضمین همیشگی linearizability', 'تبدیل خودکار replication به sharding'], 'partitioning به تنهایی تمام queryها را سریع نمی‌کند؛ partition pruning و الگوی query مهم‌اند.'],
[132, 'ADR تصمیم، زمینه، گزینه‌های کنارگذاشته‌شده و پیامدها را ثبت می‌کند. هدف مستندات حجیم نیست؛ همکار آینده باید بداند چرا راهکار فعلی انتخاب شده و چه زمانی بازنگری شود.', 'markdown:# ADR: Inventory locking\nStatus: Accepted\nContext: competing reservations across instances\nDecision: conditional update in one transaction\nConsequences: inspect affected-row count; retry transient DB conflicts', 'برای idempotency یک ADR یک‌صفحه‌ای بنویس؛ گزینه حافظه‌ای و دلیل رد آن را هم ثبت کن.', ['ADR خوب چه چیزی را حفظ می‌کند؟', 'چرایی تصمیم و پیامدهای آن', 'فقط نام کتابخانه انتخاب‌شده', 'کپی کامل همه کلاس‌های پروژه'], 'مستندات باید با تغییر تصمیم به‌روز شوند؛ تاریخچه تصمیم را بی‌صدا بازنویسی نکن.'],
[133, 'Structured logging رخداد را به فیلدهای قابل جستجو تبدیل می‌کند. requestId، traceId و orderId نقش‌های متفاوت دارند. داده شخصی و token را حذف یا mask کن؛ MDC در async خودبه‌خود همیشه منتقل نمی‌شود.', 'log.info("order_confirmed orderId={} outcome={}", orderId, "success");\n// Configure JSON output in the logging backend; do not concatenate raw user JSON.', 'یک درخواست را در logها پیدا کن؛ payload حساس نباشد و خروجی با parser JSON قابل خواندن باشد.', ['چه چیزی نباید در log عملیاتی باشد؟', 'Bearer token کامل', 'شناسه سفارش مجاز برای رهگیری', 'کد نتیجه غیرحساس'], 'خطا در propagation context را با log بدون correlation به عنوان trace کامل معرفی نکن.'],
[134, 'Counter رخداد تجمعی، gauge وضعیت لحظه‌ای و timer توزیع مدت را نشان می‌دهد. label پرکاردینال مانند userId یا orderId هزینه ذخیره را منفجر می‌کند؛ آن‌ها برای log/trace مناسب‌ترند.', 'Timer.Sample sample = Timer.start(registry);\ntry { placeOrder(); }\nfinally { sample.stop(registry.timer("orders.place", "outcome", "attempted")); }', 'برای ثبت سفارش timer و counter نتیجه اضافه کن؛ تعداد series با تعداد سفارش‌ها رشد نکند.', ['کدام label برای metric خطرناک‌تر است؟', 'orderId یکتا برای هر درخواست', 'outcome با مقادیر success/failure', 'نام ثابت endpoint template'], 'ثبت attempted به جای success را در نام metric واضح کن؛ اندازه‌گیری نباید ادعای موفقیت غلط بسازد.'],
[135, 'Trace مسیر درخواست را با spanهای مرتبط نشان می‌دهد. context باید از HTTP و message header منتقل شود؛ ساخت trace تازه در هر سرویس زنجیره را می‌شکند. sampling و حذف داده حساس بخشی از طراحی است.', 'text:HTTP request -> server span\nDB query -> child span\nMessage -> propagated trace context\nConsumer -> linked/continued processing span', 'یک درخواست دارای DB و event را رهگیری کن؛ traceId در log قابل تطبیق و header قابل انتقال باشد.', ['برای اتصال spanهای دو سرویس چه چیزی لازم است؟', 'propagation استاندارد trace context', 'نام یکسان کلاس Java', 'اشتراک همان thread میان ماشین‌ها'], 'traceId را authentication token فرض نکن؛ قابل اعتمادبودن داده ورودی را جدا بسنج.'],
[136, 'Instrumentation باید سؤال عملیاتی را پاسخ دهد: کدام مرحله سفارش کند یا ناموفق است؟ از instrument خودکار موجود استفاده کن و فقط span دامنه معنادار اضافه کن. error و exception را با semantics صحیح ثبت کن.', 'Observation.createNotStarted("orders.reserve", observationRegistry)\n    .observe(() -> inventory.reserve(productId, quantity));', 'رزرو ناموفق و کند را ایجاد کن؛ در metric/trace بتوانی علت مرحله را از کل request جدا کنی.', ['span دامنه مفید چه ویژگی دارد؟', 'مرز عملیاتی معنادار با هزینه و داده محدود', 'یک span برای هر getter', 'ثبت password به عنوان attribute'], 'instrumentation دوبل agent و library می‌تواند span تکراری و هزینه اضافه بسازد.'],
[137, 'Prometheus سری زمانی metric را scrape می‌کند؛ Grafana آن را نمایش می‌دهد. dashboard باید نرخ، خطا، مدت و اشباع را کنار هم نشان دهد. histogram quantile با میانگین متفاوت است و bucket مناسب می‌خواهد.', 'promql:sum(rate(http_server_requests_seconds_count[5m]))\n# Request rate; filter service labels in a real multi-service deployment.', 'نرخ درخواست و خطا را روی یک بازه یکسان نمایش بده؛ restart counter نباید نرخ منفی بسازد.', ['چرا rate روی counter استفاده می‌شود؟', 'محاسبه نرخ با درنظرگرفتن reset شمارنده', 'برای تبدیل UUID به label', 'برای حذف نیاز به window زمانی'], 'میانگین‌گرفتن p95 چند instance، p95 کل سرویس را درست نمی‌سازد.'],
[138, 'SLI رفتار اندازه‌گیری‌شده کاربر و SLO هدف آن است. error budget حد مجاز شکست در بازه مشخص است؛ alert روی burn rate می‌تواند زودتر از پایان budget هشدار دهد. هر alert باید action مشخص داشته باشد.', 'text:SLO: 99.9% successful checkout requests over 30 days\nDefine denominator, exclusions, latency target and data source explicitly.\nAlert: sustained fast budget burn -> investigate checkout dependency health.', 'برای checkout یک SLI و یک alert قابل اقدام بنویس؛ تعریف request موفق و ناموفق مبهم نباشد.', ['تفاوت SLI و SLO چیست؟', 'SLI اندازه‌گیری و SLO هدف آن است', 'هر دو فقط درصد CPU هستند', 'SLO همان نام dashboard است'], 'هشدار بدون owner و runbook احتمال alert fatigue را بالا می‌برد.'],
[139, 'Multi-stage build ابزار ساخت را از runtime جدا می‌کند. lock نسخه dependency و wrapper تکرارپذیری را بهتر می‌کنند؛ cache فقط بهینه‌سازی است. build بومی ARM64 برای مک نیاز به اجبار amd64 ندارد.', 'dockerfile:FROM maven:3.9-eclipse-temurin-25 AS build\nWORKDIR /src\nCOPY . .\nRUN mvn -B package\nFROM eclipse-temurin:25-jre\nWORKDIR /app\nCOPY --from=build /src/target/app.jar app.jar\nUSER 10001\nENTRYPOINT ["java", "-jar", "app.jar"]', 'finalName را app تنظیم و image را بساز؛ final stage نباید Maven یا سورس داشته باشد.', ['مزیت اصلی stage runtime چیست؟', 'نبود ابزار build و سطح حمله/حجم کمتر', 'دانلود dependency در هر startup', 'تضمین خودکار correctness کد'], 'برای عبور build از -DskipTests بی‌دلیل استفاده نکن.'],
[140, 'Compose شبکه سرویس‌ها را با DNS نام سرویس می‌سازد. ports برای دسترسی host است؛ سرویس داخل شبکه از پورت داخلی استفاده می‌کند. volume داده را از چرخه container جدا می‌کند.', 'yaml:services:\n  app:\n    environment:\n      SPRING_DATASOURCE_URL: jdbc:postgresql://db:5432/orders\n  db:\n    image: postgres:17-alpine', 'تفاوت localhost از host و container را با اتصال DB توضیح بده؛ حذف container بدون حذف volume داده را حفظ کند.', ['از داخل app، localhost به کجا اشاره می‌کند؟', 'خود container اپ', 'به طور خودکار سرویس db', 'تمام hostهای شبکه Docker'], 'فایل Compose آموزشی را کامل کن؛ نمونه fragment به تنهایی تنظیم امن production نیست.'],
[141, 'Pipeline باید artifact را یک بار بسازد و همان artifact را در محیط‌ها ارتقا دهد. test، scan و migration gateها باید شکست را متوقف کنند. deploy با tag شناور قابلیت بازتولید را کم می‌کند.', 'text:checkout -> verify -> build image -> scan -> publish immutable digest\n-> deploy staging -> smoke tests -> approve production -> deploy same digest', 'digest دو محیط را مقایسه کن؛ staging و production باید همان build را با config جدا اجرا کنند.', ['چرا promote همان artifact بهتر است؟', 'تفاوت پنهان build میان محیط‌ها کم می‌شود', 'دیگر هیچ smoke test لازم نیست', 'secret باید داخل image ثابت قرار گیرد'], 'secret و config محیط را در build artifact جاسازی نکن.'],
[142, 'Pipeline پروژه باید با یک command قابل اجرای محلی هم باشد. تست DB واقعی به Docker runner نیاز دارد؛ reportها را در شکست هم ذخیره کن. انتشار image نباید پیش از عبور gateهای لازم رخ دهد.', 'yaml:steps:\n  - run: ./mvnw -B verify\n  - run: docker build -t orders:${GIT_SHA} .\n  # Publish only after successful verification and scanning.', 'یک تست قرمز و یک خطای build ایجاد کن؛ هیچ artifact نامعتبر نباید به مرحله انتشار برسد.', ['هدف اجرای verify پیش از publish چیست؟', 'جلوگیری از انتشار artifact با تست شکست‌خورده', 'تبدیل تست‌ها به مستندات HTML فقط', 'حذف وابستگی به JDK برای build'], 'cache ناسالم یا قدیمی نباید باعث عبور تستی شود که واقعاً اجرا نشده است.'],
[143, 'Startup probe برای شروع کند، readiness برای دریافت ترافیک و liveness برای گیرکردن process است. endpointها باید سبک و کم‌وابستگی باشند. resource request/limit بر scheduling و رفتار runtime اثر دارد.', 'yaml:readinessProbe:\n  httpGet:\n    path: /actuator/health/readiness\n    port: 8080\nlivenessProbe:\n  httpGet:\n    path: /actuator/health/liveness\n    port: 8080', 'زمان شروع کند و قطع DB را شبیه‌سازی کن؛ restart storm رخ ندهد و ترافیک به instance آماده برود.', ['readiness ناموفق چه اثری باید داشته باشد؟', 'حذف از مسیر ترافیک، نه الزاماً restart', 'حذف فوری تمام volumeها', 'تغییر خودکار schema'], 'liveness را به همه وابستگی‌های مشترک وصل نکن.'],
[144, 'Rollback image وقتی schema سازگار مانده ساده‌تر است. انتشار expand/contract اجازه می‌دهد نسخه قدیم و جدید مدتی همزیستی کنند. smoke test پس از deploy باید مسیر واقعی و محدود را بسنجد.', 'text:Deploy 1: add nullable column\nDeploy 2: write/read new field with compatibility\nBackfill and observe\nDeploy 3: remove old field after old clients are gone', 'کد قبلی را پس از migration جدید اجرا کن؛ اگر ناسازگار است rollback plan را اصلاح کن.', ['چرا expand/contract مفید است؟', 'حفظ سازگاری طی rollout و rollback کد', 'حذف نیاز به backup برای همیشه', 'اجرای خودکار تمام migrationهای معکوس'], 'برگشت image به تنهایی داده حذف‌شده را بازیابی نمی‌کند.'],
[145, 'SIGTERM باید فرصت پایان درخواست‌های درحال‌اجرا را بدهد. ابتدا از routing خارج شو و سپس با deadline منطقی shutdown کن. زمان توقف container باید از بودجه drain کوتاه‌تر نباشد.', 'yaml:server:\n  shutdown: graceful\nspring:\n  lifecycle:\n    timeout-per-shutdown-phase: 20s', 'در حین یک درخواست کند SIGTERM بده؛ در deadline مجاز درخواست تمام و کار جدید پذیرفته نشود.', ['چرا stop timeout باید با graceful shutdown هماهنگ باشد؟', 'تا SIGKILL زودهنگام کارهای درحال‌اجرا را قطع نکند', 'برای افزایش خودکار حجم heap', 'برای خاموش‌کردن validation'], 'کار async و consumer نیز lifecycle جدا دارند؛ فقط HTTP را بررسی نکن.'],
[146, 'تیونینگ با baseline و یک فرضیه آغاز می‌شود؛ همزمان چند flag عوض نکن. pause، throughput، allocation و RSS را با نیاز کاربر بسنج. GC متفاوت درمان query کند یا صف pool اشباع نیست.', 'bash:java -Xlog:gc*:file=/tmp/gc.log -XX:StartFlightRecording=duration=60s,filename=/tmp/run.jfr -jar app.jar', 'یک run ثابت را دو بار با تنها یک تغییر اجرا کن؛ p95، error و حافظه را ثبت کن.', ['برای query کند اولین درمان منطقی چیست؟', 'تحلیل query و زمان انتظار، نه تغییر تصادفی GC', 'همیشه افزایش تعداد GC thread', 'خاموش‌کردن تمام monitoring'], 'نتیجه benchmark لپ‌تاپ را به SLA production تبدیل نکن.'],
[147, 'Threat model دارایی، مرز اعتماد، مهاجم و مسیر سوءاستفاده را مشخص می‌کند. failure test می‌سنجد سیستم زیر قطع شبکه، DB کند یا پیام تکراری چه می‌کند. آزمایش باید محدود، قابل توقف و ترجیحاً محیط جدا باشد.', 'text:Asset: customer order data\nBoundary: authenticated API -> order lookup\nThreat: user A reads user B order\nControl: principal-scoped query + authorization tests', 'سه تهدید و سه failure برای checkout بنویس؛ برای هرکدام کنترل و شاهد تست مشخص کن.', ['آزمایش failure امن چه ویژگی دارد؟', 'دامنه محدود، rollback/stop plan و مشاهده‌پذیری', 'قطع تصادفی سرویس واقعی بدون هماهنگی', 'فقط پنهان‌کردن exceptionها از log'], 'فهرست ابزار امنیتی جای تحلیل مرز اعتماد و مالکیت داده را نمی‌گیرد.'],
[148, 'Bottleneck را از trace و profiling پیدا و با یک تغییر کوچک درمان کن. اگر pool DB اشباع است، اول مدت query و transaction را ببین؛ زیادکردن pool ممکن است رقابت را بیشتر کند.', 'text:Hypothesis: N+1 extends DB connection hold time\nChange: projection + bounded page\nVerify: query count, pool wait, p95, error rate under same load', 'گزارش قبل/بعد با workload یکسان بساز؛ اگر فرضیه رد شد آن را ثبت و تغییر بی‌فایده را برگردان.', ['بهبود قابل دفاع چه شواهدی دارد؟', 'مقایسه کنترل‌شده با خطا و latency و throughput', 'فقط احساس سریع‌ترشدن یک reload', 'یک عدد بدون شرح محیط'], 'بهینه‌سازی نباید correctness مانند کنترل موجودی را قربانی کند.'],
[149, 'Runbook برای حادثه باید علائم، بررسی‌های کم‌خطر، اقدام و escalation داشته باشد. ابتدا اثر کاربر و scope را مشخص کن؛ تغییرات را ثبت کن تا علت و recovery قابل پیگیری بماند.', 'markdown:# Checkout latency incident\n1. Check error rate and dependency latency.\n2. Compare DB pool wait and active queries.\n3. Stop the rollout if regression began after deploy.\n4. Escalate to the service owner; preserve relevant traces.', 'برای backlog صف یک runbook یک‌صفحه‌ای بنویس؛ purge بدون بررسی نباید اقدام پیش‌فرض باشد.', ['اولویت پاسخ حادثه چیست؟', 'کاهش اثر کاربر با اقدام قابل کنترل و شواهد', 'اثبات مقصر پیش از بازیابی', 'حذف logها برای کاهش خطاهای dashboard'], 'در گزارش حادثه secret یا داده شخصی مشتری را بازنشر نکن.'],
[150, 'آمادگی انتشار از build سبز فراتر است: rollback، backup restore، کنترل دسترسی، observability و محدودیت منابع لازم‌اند. هر مورد checklist باید شاهد داشته باشد؛ برچسب production-ready بدون اجرا معتبر نیست.', 'text:Release evidence:\n- tests and migration rehearsal\n- authentication + ownership checks\n- restore rehearsal\n- load/error budget baseline\n- rollback/runbook owner', 'برای پروژه خود به هر مورد لینک log، تست یا سند بده؛ موارد اجرا‌نشده را صریح علامت بزن.', ['چه چیزی شاهد آمادگی واقعی است؟', 'تست و rehearsal ثبت‌شده برای ریسک‌های مهم', 'فقط عبارت enterprise در README', 'فقط زیادبودن تعداد کلاس‌ها'], 'امنیت آموزشی ساده و محیط local را از تنظیمات production تفکیک کن.'],
[151, 'مرور Core باید با تحلیل کد انجام شود: equality، generic variance، exception، immutability و JMM. پاسخ حفظی بدون مثال مرزی کافی نیست. برای هر موضوع یک bug کوچک را توضیح و اصلاح کن.', 'var a = new BigDecimal("1.0");\nvar b = new BigDecimal("1.00");\nSystem.out.println(a.equals(b));\nSystem.out.println(a.compareTo(b) == 0);', 'پیش از اجرا دو خروجی را پیش‌بینی کن؛ سپس کاربرد هر مقایسه در دامنه پول را توضیح بده.', ['خروجی دو مقایسه نمونه چیست؟', 'false سپس true', 'true سپس false', 'هر دو true چون مقدار عددی یکسان است'], 'قرارداد equals/hashCode باید با keyهای HashMap و مفهوم equality دامنه سازگار باشد.'],
[152, 'مرور Spring/JPA روی مرزهای runtime متمرکز است: proxy، transaction، persistence context و query count. برای هر annotation بگو چه زیرساختی لازم است و چه فراخوانی آن را دور می‌زند.', 'class Example {\n    void outer() { this.inner(); }\n    @Transactional void inner() { /* work */ }\n}\n// Discuss proxy-based invocation before claiming a transaction exists.', 'self-invocation، N+1 و rollback checked exception را با یک تست برای هرکدام توضیح بده.', ['وجود @Transactional روی inner در نمونه چه تضمینی می‌دهد؟', 'به تنهایی عبور از proxy و فعال‌شدن transaction را تضمین نمی‌کند', 'همیشه تمام outer را تراکنشی می‌کند', 'هیچ متدی در Spring نمی‌تواند تراکنشی باشد'], 'نام annotation را به جای توضیح مرز و رفتار واقعی پاسخ نده.'],
[153, 'در مصاحبه system design ابتدا requirement و عددهای ظرفیت را روشن کن. جریان حیاتی، مدل داده و failureها را پیش از افزودن ابزار بکش. از فرض‌ها دفاع کن و راه ساده‌تر را هم مقایسه کن.', 'text:Clarify -> estimate -> API/data model -> critical flow\n-> consistency/failures -> bottlenecks -> observability -> trade-offs', 'در ۲۰ دقیقه طراحی رزرو موجودی ارائه بده؛ دو failure و دلیل انتخاب lock یا conditional update را پوشش بده.', ['پیش از انتخاب Kafka یا Redis چه لازم است؟', 'شناخت مسئله، ظرفیت و ضمانت‌های موردنیاز', 'فقط شمارش اسم ابزارها', 'ساختن ده microservice مستقل از نیاز'], 'اعداد تخمینی را فرض بنام و اثر حساسیت آن‌ها را بررسی کن.'],
[154, 'README پروژه باید مسیر اجرای قابل تکرار، داده آزمایشی، API، تست و محدودیت‌های واقعی داشته باشد. ادعای JWT، relay outbox یا CI فقط وقتی مجاز است که همان قابلیت پیاده و بررسی شده باشد.', 'markdown:# Local run\nPrerequisites: Docker; JDK 25 for local Java commands\nCommands: build, test, start, stop\nDocument: sample requests, credentials, migrations, known limitations', 'از checkout تازه، README را قدم‌به‌قدم اجرا کن؛ هر فرمان یا مسیر خراب را اصلاح کن.', ['README قابل اعتماد چه ویژگی دارد؟', 'فرمان‌های اجراشده و محدودیت‌های صریح', 'فقط فهرست تکنولوژی‌های برنامه‌ریزی‌شده', 'پنهان‌کردن تست‌های شکست‌خورده'], 'کد نمونه آموزشی را بدون threat model و تست production معرفی نکن.'],
[155, 'مسئله موجودی آخرین کالا آزمون خوبی برای DB و concurrency است. راهکار باید در چند instance هم کار کند؛ lock حافظه JVM کافی نیست. rollback، deadlock و duplicate request را در پاسخ لحاظ کن.', 'sql:UPDATE inventory SET available_quantity=available_quantity-1\nWHERE product_id=:id AND available_quantity>=1;', 'دو connection روی موجودی یک بساز؛ affected rowها، rollback و retry کل تراکنش را توضیح بده.', ['چرا synchronized کافی نیست؟', 'بین JVMهای مختلف مشترک نیست', 'هیچ عملیات حافظه‌ای را محافظت نمی‌کند', 'چون PostgreSQL از integer پشتیبانی نمی‌کند'], 'تست thread همزمان در یک process، سناریوی چند instance با اتصال مستقل را جایگزین نمی‌کند.'],
[156, 'ارزیابی نهایی را بر اجرای کار بسنج: از checkout تا deploy محلی، تست API و عیب‌یابی یک failure. «خوانده‌شده» با «مهارت اثبات‌شده» یکی نیست. شکاف‌های باقی‌مانده را به تمرین بعدی تبدیل کن.', 'text:Final exercise:\n1. Build and run from a fresh checkout.\n2. Create/read an order and reject invalid/unauthorized requests.\n3. Demonstrate rollback and concurrent reservation.\n4. Explain one failure using logs/metrics.\n5. Restore a backup into a separate DB.', 'یک گزارش اجرای نهایی با نتیجه هر مرحله و محدودیت‌ها بساز؛ مرحله اجرا‌نشده را پاس‌شده اعلام نکن.', ['معیار پایان مسیر چیست؟', 'توانایی ساخت، تست، توضیح و عیب‌یابی رفتار واقعی', 'صرفاً تکمیل ۱۵۶ checkbox', 'حفظ نام همه annotationها'], 'پس از دوره، ضعف مشخص را با تمرین هدفمند ادامه بده؛ تعداد درس معادل سطح شغلی تضمینی نیست.'],
];
